      const layerFeatures = allLayerFeatures[editableLayerItem.id] || [];

      const geojsonData = {
        type: "FeatureCollection" as const,
        features: layerFeatures.map(f => ({
          type: "Feature" as const,
          geometry: {
            type: f.geometryType,
            coordinates: f.coordinates,
          },
          properties: {
            featureId: f.id,
            ...f.properties,
          },
        })),
      };

