import { useState, useEffect, useRef, useCallback, useMemo } from "react";
import { useVirtualizer } from "@tanstack/react-virtual";
import { getFieldLabel } from "@shared/field-labels";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Badge } from "@/components/ui/badge";
import { Checkbox } from "@/components/ui/checkbox";
import { DraggableModal } from "@/components/ui/draggable-modal";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/ui/tooltip";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Switch } from "@/components/ui/switch";
import { Settings2, Plus, Trash2, Save, X, Search, ArrowDown, ArrowUpDown, ArrowUp, Filter, CheckSquare, Square, Undo2, Crosshair } from "lucide-react";
import type { DrawnFeature, AttributeField, AttributeFieldType, LayerSchemaDefinition } from "@shared/schema";

interface PendingEdit {
  featureId: number;
  originalProperties: Record<string, unknown>;
  newProperties: Record<string, unknown>;
}

interface AttributeTableCloseRef {
  tryClose: () => boolean;
}

interface AttributeTableProps {
  features: DrawnFeature[];
  selectedFeatureIds: number[];
  layerSchema: LayerSchemaDefinition | null;
  onFeatureSelect: (featureId: number, multi?: boolean) => void;
  onFeatureUpdate: (featureId: number, properties: Record<string, unknown>) => void;
  onBatchUpdate?: (updates: { id: number; properties: Record<string, unknown> }[]) => Promise<void>;
  onBatchDelete?: (ids: number[]) => void;
  onSchemaUpdate: (fields: AttributeField[]) => void;
  onSelectAll?: (featureIds: number[]) => void;
  onClearSelection?: () => void;
  onZoomToFeature?: (feature: DrawnFeature) => void;
  onRequestClose?: (hasUnsavedChanges: boolean) => void;
  closeRef?: React.MutableRefObject<AttributeTableCloseRef | null>;
  layerName: string;
}

type SortDirection = "asc" | "desc" | null;
type SortConfig = { column: string; direction: SortDirection };
type ColumnFilters = Record<string, string>;

const FIELD_TYPE_LABELS: Record<AttributeFieldType, string> = {
  text: "Текст",
  number: "Число",
  date: "Дата",
  boolean: "Да/Нет",
  select: "Список",
};

const ROW_HEIGHT = 36;

export function AttributeTable({
  features,
  selectedFeatureIds,
  layerSchema,
  onFeatureSelect,
  onFeatureUpdate,
  onBatchUpdate,
  onBatchDelete,
  onSchemaUpdate,
  onSelectAll,
  onClearSelection,
  onZoomToFeature,
  onRequestClose,
  closeRef,
  layerName,
}: AttributeTableProps) {
  const [showSchemaDialog, setShowSchemaDialog] = useState(false);
  const [editingFields, setEditingFields] = useState<AttributeField[]>([]);
  const [editingCell, setEditingCell] = useState<{ featureId: number; field: string } | null>(null);
  const [editValue, setEditValue] = useState<string>("");
  const [searchQuery, setSearchQuery] = useState("");
  const [hasScrolledToSelected, setHasScrolledToSelected] = useState(false);
  const [sortConfig, setSortConfig] = useState<SortConfig>({ column: "", direction: null });
  const [columnFilters, setColumnFilters] = useState<ColumnFilters>({});

  const [pendingEdits, setPendingEdits] = useState<Map<number, PendingEdit>>(new Map());
  const [undoStack, setUndoStack] = useState<PendingEdit[]>([]);
  const [isSaving, setIsSaving] = useState(false);
  const [showCloseConfirm, setShowCloseConfirm] = useState(false);

  const hasPendingChanges = pendingEdits.size > 0;
  const canUndo = undoStack.length > 0;

  const handleCloseRequest = useCallback(() => {
    if (hasPendingChanges) {
      setShowCloseConfirm(true);
    } else {
      onRequestClose?.(false);
    }
  }, [hasPendingChanges, onRequestClose]);

  const handleDiscardAndClose = useCallback(() => {
    setPendingEdits(new Map());
    setUndoStack([]);
    setShowCloseConfirm(false);
    onRequestClose?.(false);
  }, [onRequestClose]);

  const handleSaveAndClose = useCallback(async () => {
    if (onBatchUpdate && pendingEdits.size > 0) {
      setIsSaving(true);
      try {
        const updates = Array.from(pendingEdits.values())
          .filter(edit => typeof edit.featureId === 'number' && !isNaN(edit.featureId))
          .map(edit => ({
            id: edit.featureId,
            properties: edit.newProperties,
          }));
        if (updates.length > 0) {
          await onBatchUpdate(updates);
        }
        setPendingEdits(new Map());
        setUndoStack([]);
        setShowCloseConfirm(false);
        onRequestClose?.(false);
      } finally {
        setIsSaving(false);
      }
    }
  }, [onBatchUpdate, pendingEdits, onRequestClose]);

  useEffect(() => {
    if (closeRef) {
      closeRef.current = {
        tryClose: () => {
          if (hasPendingChanges) {
            setShowCloseConfirm(true);
            return true;
          }
          return false;
        },
      };
    }
    return () => {
      if (closeRef) {
        closeRef.current = null;
      }
    };
  }, [closeRef, hasPendingChanges]);

  const fields = layerSchema?.fields || [];

  const [columnWidths, setColumnWidths] = useState<Record<string, number>>({
    _checkbox: 40,
    _id: 60,
    _type: 80,
  });
  const resizingRef = useRef<{ column: string; startX: number; startWidth: number } | null>(null);
  const parentRef = useRef<HTMLDivElement>(null);

  const filteredAndSortedFeatures = useMemo(() => {
    let result = [...features];

    // Apply global search filter
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      result = result.filter(feature => {
        if (feature.id.toString().includes(query)) return true;
        if (feature.geometryType.toLowerCase().includes(query)) return true;

        for (const value of Object.values(feature.properties)) {
          if (value !== null && value !== undefined) {
            if (value.toString().toLowerCase().includes(query)) {
              return true;
            }
          }
        }
        return false;
      });
    }

    // Apply column filters
    Object.entries(columnFilters).forEach(([column, filterValue]) => {
      if (!filterValue.trim()) return;

      const filter = filterValue.toLowerCase();
      result = result.filter(feature => {
        if (column === "_id") {
          return feature.id.toString().includes(filter);
        }
        if (column === "_type") {
          const typeLabel = feature.geometryType === "Point" ? "точка" : 
                           feature.geometryType === "LineString" ? "линия" : "полигон";
          return typeLabel.includes(filter) || feature.geometryType.toLowerCase().includes(filter);
        }
        const value = feature.properties[column];
        if (value === null || value === undefined) return false;
        return value.toString().toLowerCase().includes(filter);
      });
    });

    // Apply sorting
    if (sortConfig.column && sortConfig.direction) {
      result.sort((a, b) => {
        let aVal: unknown;
        let bVal: unknown;

        if (sortConfig.column === "_id") {
          aVal = a.id;
          bVal = b.id;
        } else if (sortConfig.column === "_type") {
          aVal = a.geometryType;
          bVal = b.geometryType;
        } else {
          aVal = a.properties[sortConfig.column];
          bVal = b.properties[sortConfig.column];
        }

        // Handle null/undefined
        if (aVal === null || aVal === undefined) aVal = "";
        if (bVal === null || bVal === undefined) bVal = "";

        // Compare
        let comparison = 0;
        if (typeof aVal === "number" && typeof bVal === "number") {
          comparison = aVal - bVal;
        } else {
          comparison = String(aVal).localeCompare(String(bVal), "ru");
        }

        return sortConfig.direction === "desc" ? -comparison : comparison;
      });
    }

    return result;
  }, [features, searchQuery, columnFilters, sortConfig]);

  const filteredFeatures = filteredAndSortedFeatures;

  const handleSort = useCallback((column: string) => {
    setSortConfig(prev => {
      if (prev.column !== column) {
        return { column, direction: "asc" };
      }
      if (prev.direction === "asc") {
        return { column, direction: "desc" };
      }
      return { column: "", direction: null };
    });
  }, []);

  const handleColumnFilterChange = useCallback((column: string, value: string) => {
    setColumnFilters(prev => ({
      ...prev,
      [column]: value
    }));
  }, []);

  const handleSelectAll = useCallback(() => {
    if (onSelectAll) {
      const allIds = filteredFeatures.map(f => f.id);
      onSelectAll(allIds);
    }
  }, [filteredFeatures, onSelectAll]);

  const handleClearSelection = useCallback(() => {
    if (onClearSelection) {
      onClearSelection();
    }
  }, [onClearSelection]);

  const handleCheckboxChange = useCallback((featureId: number, checked: boolean) => {
    // Use multi=true mode for checkbox behavior
    onFeatureSelect(featureId, true);
  }, [onFeatureSelect]);

  const rowVirtualizer = useVirtualizer({
    count: filteredFeatures.length,
    getScrollElement: () => parentRef.current,
    estimateSize: () => ROW_HEIGHT,
    overscan: 10,
  });

  const [currentSelectedIndex, setCurrentSelectedIndex] = useState(0);

  const scrollToSelectedByIndex = useCallback((indexInSelection: number) => {
    if (selectedFeatureIds.length === 0) return;

    const safeIndex = indexInSelection % selectedFeatureIds.length;
    const targetId = selectedFeatureIds[safeIndex];
    const rowIndex = filteredFeatures.findIndex(f => f.id === targetId);

    if (rowIndex !== -1) {
      rowVirtualizer.scrollToIndex(rowIndex, { align: "center" });
    }
  }, [selectedFeatureIds, filteredFeatures, rowVirtualizer]);

  const scrollToNextSelected = useCallback(() => {
    if (selectedFeatureIds.length === 0) return;

    const nextIndex = (currentSelectedIndex + 1) % selectedFeatureIds.length;
    setCurrentSelectedIndex(nextIndex);
    scrollToSelectedByIndex(nextIndex);
  }, [selectedFeatureIds.length, currentSelectedIndex, scrollToSelectedByIndex]);

  const prevSelectedRef = useRef<number[]>([]);

  useEffect(() => {
    const selectedChanged = JSON.stringify(prevSelectedRef.current) !== JSON.stringify(selectedFeatureIds);

    if (selectedChanged) {
      prevSelectedRef.current = selectedFeatureIds;
      setCurrentSelectedIndex(0);
      setHasScrolledToSelected(false);
    }
  }, [selectedFeatureIds]);

  useEffect(() => {
    if (!hasScrolledToSelected && selectedFeatureIds.length > 0 && filteredFeatures.length > 0) {
      const timer = setTimeout(() => {
        scrollToSelectedByIndex(0);
        setHasScrolledToSelected(true);
      }, 100);
      return () => clearTimeout(timer);
    }
  }, [hasScrolledToSelected, selectedFeatureIds, filteredFeatures, scrollToSelectedByIndex]);

  useEffect(() => {
    const newWidths: Record<string, number> = { _checkbox: 40, _id: 60, _type: 80 };
    fields.forEach((field) => {
      if (!columnWidths[field.name]) {
        newWidths[field.name] = 120;
      } else {
        newWidths[field.name] = columnWidths[field.name];
      }
    });
    setColumnWidths(newWidths);
  }, [fields]);

  const handleResizeStart = useCallback((e: React.MouseEvent, column: string) => {
    e.preventDefault();
    e.stopPropagation();
    resizingRef.current = {
      column,
      startX: e.clientX,
      startWidth: columnWidths[column] || 100,
    };

    const handleMouseMove = (moveEvent: MouseEvent) => {
      if (!resizingRef.current) return;
      const delta = moveEvent.clientX - resizingRef.current.startX;
      const newWidth = Math.max(40, resizingRef.current.startWidth + delta);
      setColumnWidths(prev => ({ ...prev, [resizingRef.current!.column]: newWidth }));
    };

    const handleMouseUp = () => {
      resizingRef.current = null;
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleMouseUp);
    };

    document.addEventListener("mousemove", handleMouseMove);
    document.addEventListener("mouseup", handleMouseUp);
  }, [columnWidths]);

  useEffect(() => {
    if (showSchemaDialog) {
      setEditingFields(fields.length > 0 ? [...fields] : []);
    }
  }, [showSchemaDialog, fields]);

  const handleAddField = () => {
    setEditingFields([
      ...editingFields,
      { name: "", type: "text", required: false },
    ]);
  };

  const handleRemoveField = (index: number) => {
    setEditingFields(editingFields.filter((_, i) => i !== index));
  };

  const handleFieldChange = (index: number, updates: Partial<AttributeField>) => {
    setEditingFields(editingFields.map((field, i) => 
      i === index ? { ...field, ...updates } : field
    ));
  };

  const handleSaveSchema = () => {
    const validFields = editingFields.filter(f => f.name.trim() !== "");
    onSchemaUpdate(validFields);
    setShowSchemaDialog(false);
  };

  const startEditing = (featureId: number, field: string, currentValue: unknown) => {
    setEditingCell({ featureId, field });
    setEditValue(currentValue?.toString() || "");
  };

  const getFeatureProperties = useCallback((featureId: number): Record<string, unknown> => {
    const pending = pendingEdits.get(featureId);
    if (pending) {
      return pending.newProperties;
    }
    const feature = features.find(f => f.id === featureId);
    return feature?.properties || {};
  }, [pendingEdits, features]);

  const saveEdit = useCallback(() => {
    if (!editingCell) return;
    if (typeof editingCell.featureId !== 'number' || isNaN(editingCell.featureId)) return;

    const feature = features.find(f => f.id === editingCell.featureId);
    if (!feature) return;

    const fieldDef = fields.find(f => f.name === editingCell.field);
    let parsedValue: unknown = editValue;

    if (fieldDef?.type === "number") {
      parsedValue = parseFloat(editValue) || 0;
    } else if (fieldDef?.type === "boolean") {
      parsedValue = editValue === "true";
    }

    const currentProps = getFeatureProperties(editingCell.featureId);
    const newProperties = {
      ...currentProps,
      [editingCell.field]: parsedValue,
    };

    const existingPending = pendingEdits.get(editingCell.featureId);
    const originalProperties = existingPending?.originalProperties || feature.properties;

    setPendingEdits(prev => {
      const newMap = new Map(prev);
      newMap.set(editingCell.featureId, {
        featureId: editingCell.featureId,
        originalProperties,
        newProperties,
      });
      return newMap;
    });

    setUndoStack(prev => [...prev, {
      featureId: editingCell.featureId,
      originalProperties: currentProps,
      newProperties,
    }]);

    setEditingCell(null);
    setEditValue("");
  }, [editingCell, features, fields, editValue, getFeatureProperties, pendingEdits]);

  const cancelEdit = () => {
    setEditingCell(null);
    setEditValue("");
  };

  const handleSaveAllChanges = useCallback(async () => {
    if (!onBatchUpdate || pendingEdits.size === 0) return;

    setIsSaving(true);
    try {
      const allEdits = Array.from(pendingEdits.values());

      const updates = allEdits
        .filter(edit => typeof edit.featureId === 'number' && !isNaN(edit.featureId) && edit.featureId > 0)
        .map(edit => ({
          id: edit.featureId,
          properties: edit.newProperties,
        }));

      if (updates.length > 0) {
        await onBatchUpdate(updates);
      }
      setPendingEdits(new Map());
      setUndoStack([]);
    } finally {
      setIsSaving(false);
    }
  }, [onBatchUpdate, pendingEdits]);

  const handleUndo = useCallback(() => {
    if (undoStack.length === 0) return;

    const lastAction = undoStack[undoStack.length - 1];
    setUndoStack(prev => prev.slice(0, -1));

    setPendingEdits(prev => {
      const newMap = new Map(prev);
      const existingPending = newMap.get(lastAction.featureId);

      if (existingPending) {
        const feature = features.find(f => f.id === lastAction.featureId);
        if (JSON.stringify(lastAction.originalProperties) === JSON.stringify(feature?.properties)) {
          newMap.delete(lastAction.featureId);
        } else {
          newMap.set(lastAction.featureId, {
            ...existingPending,
            newProperties: lastAction.originalProperties,
          });
        }
      }
      return newMap;
    });
  }, [undoStack, features]);

  const handleDeleteSelected = useCallback(() => {
    if (!onBatchDelete || selectedFeatureIds.length === 0) return;
    onBatchDelete(selectedFeatureIds);
  }, [onBatchDelete, selectedFeatureIds]);

  const handleZoomToSelected = useCallback(() => {
    if (!onZoomToFeature || selectedFeatureIds.length === 0) return;
    const targetId = selectedFeatureIds[selectedFeatureIds.length > 1 ? currentSelectedIndex : 0];
    const feature = features.find(f => f.id === targetId);
    if (feature) {
      onZoomToFeature(feature);
    }
  }, [onZoomToFeature, selectedFeatureIds, currentSelectedIndex, features]);

  const renderCellValue = (feature: DrawnFeature, field: AttributeField) => {
    const pendingEdit = pendingEdits.get(feature.id);
    const displayValue = pendingEdit ? pendingEdit.newProperties[field.name] : feature.properties[field.name];
    const isEditing = editingCell?.featureId === feature.id && editingCell?.field === field.name;
    const hasChange = pendingEdit && pendingEdit.newProperties[field.name] !== pendingEdit.originalProperties[field.name];

    if (isEditing) {
      if (field.type === "boolean") {
        return (
          <Switch
            checked={editValue === "true"}
            onCheckedChange={(checked) => {
              setEditValue(checked.toString());
              setTimeout(saveEdit, 0);
            }}
            autoFocus
          />
        );
      }

      if (field.type === "select" && field.options) {
        return (
          <Select 
            value={editValue} 
            onValueChange={(val) => {
              setEditValue(val);
              setTimeout(saveEdit, 0);
            }}
          >
            <SelectTrigger className="h-7 text-xs">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              {field.options.map((opt) => (
                <SelectItem key={opt} value={opt}>{opt}</SelectItem>
              ))}
            </SelectContent>
          </Select>
        );
      }

      return (
        <Input
          value={editValue}
          onChange={(e) => setEditValue(e.target.value)}
          className="h-7 text-xs"
          type={field.type === "number" ? "number" : field.type === "date" ? "date" : "text"}
          onKeyDown={(e) => {
            if (e.key === "Enter") saveEdit();
            if (e.key === "Escape") cancelEdit();
          }}
          onBlur={saveEdit}
          autoFocus
        />
      );
    }

    if (field.type === "boolean") {
      return (
        <Badge 
          variant={displayValue ? "default" : "secondary"} 
          className={`cursor-pointer ${hasChange ? "ring-2 ring-primary ring-offset-1" : ""}`}
          onClick={() => startEditing(feature.id, field.name, displayValue)}
        >
          {displayValue ? "Да" : "Нет"}
        </Badge>
      );
    }

    return (
      <span 
        className={`cursor-pointer hover:bg-muted px-1 rounded truncate block ${hasChange ? "bg-primary/10 ring-1 ring-primary/30" : ""}`}
        onClick={() => startEditing(feature.id, field.name, displayValue)}
      >
        {displayValue?.toString() || "-"}
      </span>
    );
  };

  const totalWidth = columnWidths._checkbox + columnWidths._id + columnWidths._type + fields.reduce((sum, f) => sum + (columnWidths[f.name] || 120), 0);

  const renderColumnHeader = (column: string, label: string, width: number, canResize = true) => {
    const isSorted = sortConfig.column === column;
    const hasFilter = columnFilters[column]?.trim();

    return (
      <div 
        key={column}
        className="relative px-1 py-1 text-left font-medium text-muted-foreground text-xs border-r select-none flex-shrink-0 flex items-center gap-0.5"
        style={{ width }}
      >
        <button
          className="flex items-center gap-0.5 hover:text-foreground transition-colors flex-1 min-w-0"
          onClick={() => handleSort(column)}
          data-testid={`sort-${column}`}
        >
          <span className="truncate">{label}</span>
          {isSorted ? (
            sortConfig.direction === "asc" ? (
              <ArrowUp className="h-3 w-3 shrink-0" />
            ) : (
              <ArrowDown className="h-3 w-3 shrink-0" />
            )
          ) : (
            <ArrowUpDown className="h-3 w-3 shrink-0 opacity-30" />
          )}
        </button>
        <Popover>
          <PopoverTrigger asChild>
            <button 
              className={`p-0.5 rounded hover:bg-muted ${hasFilter ? "text-primary" : "opacity-50 hover:opacity-100"}`}
              data-testid={`filter-${column}`}
            >
              <Filter className="h-3 w-3" />
            </button>
          </PopoverTrigger>
          <PopoverContent className="w-48 p-2" align="start">
            <Input
              placeholder="Фильтр..."
              value={columnFilters[column] || ""}
              onChange={(e) => handleColumnFilterChange(column, e.target.value)}
              className="h-7 text-xs"
              data-testid={`filter-input-${column}`}
            />
            {columnFilters[column] && (
              <Button
                size="sm"
                variant="ghost"
                className="w-full mt-1 h-6 text-xs"
                onClick={() => handleColumnFilterChange(column, "")}
              >
                Сбросить
              </Button>
            )}
          </PopoverContent>
        </Popover>
        {canResize && (
          <div
            className="absolute right-0 top-0 h-full w-1 cursor-col-resize hover:bg-primary/50"
            onMouseDown={(e) => handleResizeStart(e, column)}
            data-testid={`resize-handle-${column}`}
          />
        )}
      </div>
    );
  };

  if (features.length === 0) {
    return null;
  }

  return (
    <>
      <div className="flex flex-col h-full" data-testid="attribute-table-container">
        <div className="flex items-center justify-between gap-2 px-3 py-2 border-b shrink-0">
          <div className="flex items-center gap-2 flex-wrap">
            <span className="text-sm font-medium whitespace-nowrap" data-testid="text-layer-name">{layerName}</span>
            <Badge variant="secondary" className="text-xs" data-testid="badge-feature-count">
              {searchQuery || Object.values(columnFilters).some(v => v.trim()) 
                ? `${filteredFeatures.length} из ${features.length}` 
                : `${features.length}`}
            </Badge>
            {selectedFeatureIds.length > 0 && (
              <Badge variant="outline" className="text-xs" data-testid="badge-selected-count">
                Выбрано: {selectedFeatureIds.length}
              </Badge>
            )}
          </div>
          <div className="flex items-center gap-1">
            {onSelectAll && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    size="icon"
                    variant="ghost"
                    className="h-7 w-7 shrink-0"
                    onClick={handleSelectAll}
                    data-testid="button-select-all"
                  >
                    <CheckSquare className="h-4 w-4" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>Выделить все</TooltipContent>
              </Tooltip>
            )}
            {onClearSelection && selectedFeatureIds.length > 0 && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    size="icon"
                    variant="ghost"
                    className="h-7 w-7 shrink-0"
                    onClick={handleClearSelection}
                    data-testid="button-clear-selection"
                  >
                    <Square className="h-4 w-4" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>Снять выделение</TooltipContent>
              </Tooltip>
            )}
            {onBatchDelete && selectedFeatureIds.length > 0 && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    size="icon"
                    variant="ghost"
                    className="h-7 w-7 shrink-0 text-destructive hover:text-destructive"
                    onClick={handleDeleteSelected}
                    data-testid="button-delete-selected"
                  >
                    <Trash2 className="h-4 w-4" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>Удалить выбранные ({selectedFeatureIds.length})</TooltipContent>
              </Tooltip>
            )}
            {onZoomToFeature && selectedFeatureIds.length > 0 && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    size="icon"
                    variant="ghost"
                    className="h-7 w-7 shrink-0"
                    onClick={handleZoomToSelected}
                    data-testid="button-zoom-to-feature"
                  >
                    <Crosshair className="h-4 w-4" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>Приблизить к объекту</TooltipContent>
              </Tooltip>
            )}
            {hasPendingChanges && (
              <div className="flex items-center gap-1 border-l pl-2 ml-1">
                <Badge variant="secondary" className="text-xs">
                  Изменено: {pendingEdits.size}
                </Badge>
                {onBatchUpdate && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button
                        size="icon"
                        variant="default"
                        className="h-7 w-7 shrink-0"
                        onClick={handleSaveAllChanges}
                        disabled={isSaving}
                        data-testid="button-save-all"
                      >
                        <Save className="h-4 w-4" />
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>Сохранить все изменения</TooltipContent>
                  </Tooltip>
                )}
                {canUndo && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <Button
                        size="icon"
                        variant="ghost"
                        className="h-7 w-7 shrink-0"
                        onClick={handleUndo}
                        data-testid="button-undo"
                      >
                        <Undo2 className="h-4 w-4" />
                      </Button>
                    </TooltipTrigger>
                    <TooltipContent>Отменить изменение</TooltipContent>
                  </Tooltip>
                )}
              </div>
            )}
            <div className="relative">
              <Search className="absolute left-2 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-muted-foreground" />
              <Input
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                placeholder="Поиск..."
                className="h-7 w-40 pl-7 text-xs"
                data-testid="input-search"
              />
              {searchQuery && (
                <Button
                  size="icon"
                  variant="ghost"
                  className="absolute right-0 top-0 h-7 w-7"
                  onClick={() => setSearchQuery("")}
                >
                  <X className="h-3 w-3" />
                </Button>
              )}
            </div>
            {selectedFeatureIds.length > 0 && (
              <Tooltip>
                <TooltipTrigger asChild>
                  <Button
                    size="icon"
                    variant="ghost"
                    className="h-7 w-7 shrink-0"
                    onClick={scrollToNextSelected}
                    data-testid="button-scroll-to-selected"
                  >
                    <ArrowDown className="h-4 w-4" />
                  </Button>
                </TooltipTrigger>
                <TooltipContent>
                  {selectedFeatureIds.length > 1 
                    ? `К следующему (${currentSelectedIndex + 1}/${selectedFeatureIds.length})`
                    : "Перейти к выбранному"}
                </TooltipContent>
              </Tooltip>
            )}
            <Tooltip>
              <TooltipTrigger asChild>
                <Button
                  size="icon"
                  variant="ghost"
                  className="h-7 w-7 shrink-0"
                  onClick={() => setShowSchemaDialog(true)}
                  data-testid="button-edit-schema"
                >
                  <Settings2 className="h-4 w-4" />
                </Button>
              </TooltipTrigger>
              <TooltipContent>Настройка атрибутов</TooltipContent>
            </Tooltip>
          </div>
        </div>

        <div 
          ref={parentRef}
          className="flex-1 overflow-auto"
          style={{ minHeight: 0 }}
          data-testid="table-scroll-container"
        >
          <div style={{ width: totalWidth, minWidth: "100%" }}>
            <div className="flex border-b bg-background sticky top-0 z-10">
              <div 
                className="px-2 py-2 text-center font-medium text-muted-foreground text-xs border-r select-none flex-shrink-0 flex items-center justify-center"
                style={{ width: columnWidths._checkbox }}
                data-testid="header-checkbox"
              >
              </div>
              {renderColumnHeader("_id", "ID", columnWidths._id)}
              {renderColumnHeader("_type", "Тип", columnWidths._type)}
              {fields.map((field) => (
                <div key={field.name}>
                  {renderColumnHeader(field.name, getFieldLabel(field.name) + (field.required ? " *" : ""), columnWidths[field.name] || 120)}
                </div>
              ))}
            </div>

            <div
              style={{
                height: `${rowVirtualizer.getTotalSize()}px`,
                position: "relative",
              }}
            >
              {rowVirtualizer.getVirtualItems().map((virtualRow) => {
                const feature = filteredFeatures[virtualRow.index];
                const isSelected = selectedFeatureIds.includes(feature.id);

                return (
                  <div
                    key={feature.id}
                    className={`absolute left-0 flex cursor-pointer border-b hover:bg-muted/50 ${
                      isSelected ? "bg-accent" : ""
                    }`}
                    style={{
                      top: 0,
                      transform: `translateY(${virtualRow.start}px)`,
                      height: `${virtualRow.size}px`,
                      width: "100%",
                    }}
                    onClick={(e) => {
                      // If clicking on checkbox area, don't trigger row click
                      const target = e.target as HTMLElement;
                      if (target.closest('[data-checkbox-cell]')) return;
                      onFeatureSelect(feature.id, e.ctrlKey || e.metaKey);
                    }}
                    data-testid={`row-feature-${feature.id}`}
                  >
                    <div 
                      className="px-2 py-1.5 border-r flex items-center justify-center flex-shrink-0"
                      style={{ width: columnWidths._checkbox }}
                      data-checkbox-cell
                    >
                      <Checkbox
                        checked={isSelected}
                        onCheckedChange={(checked) => handleCheckboxChange(feature.id, !!checked)}
                        data-testid={`checkbox-feature-${feature.id}`}
                      />
                    </div>
                    <div 
                      className="px-2 py-1.5 font-mono border-r flex items-center flex-shrink-0"
                      style={{ width: columnWidths._id, fontSize: 12 }}
                    >
                      {feature.id}
                    </div>
                    <div 
                      className="px-2 py-1.5 border-r flex items-center flex-shrink-0"
                      style={{ width: columnWidths._type, fontSize: 12 }}
                    >
                      <Badge variant="outline" style={{ fontSize: 11 }}>
                        {feature.geometryType === "Point" ? "Точка" : 
                         feature.geometryType === "LineString" ? "Линия" : "Полигон"}
                      </Badge>
                    </div>
                    {fields.map((field) => (
                      <div 
                        key={field.name} 
                        className="px-2 py-1.5 border-r flex items-center flex-shrink-0 overflow-hidden"
                        style={{ width: columnWidths[field.name] || 120, fontSize: 12 }}
                      >
                        {renderCellValue(feature, field)}
                      </div>
                    ))}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>

      <DraggableModal
        isOpen={showSchemaDialog}
        onClose={() => setShowSchemaDialog(false)}
        title={`Настройка атрибутов: ${layerName}`}
        defaultWidth={700}
        defaultHeight={450}
        minWidth={500}
        minHeight={300}
      >
        <div className="flex flex-col h-full">
          <div className="px-4 py-2 border-b">
            <p className="text-sm text-muted-foreground">
              Определите поля атрибутивной таблицы для слоя "{layerName}"
            </p>
          </div>

          <ScrollArea className="flex-1 px-4">
            <div className="grid gap-4 py-4">
              {editingFields.map((field, index) => (
                <div key={index} className="grid grid-cols-12 gap-2 items-start">
                  <div className="col-span-4">
                    <Label className="text-xs text-muted-foreground">Название</Label>
                    <Input
                      value={field.name}
                      onChange={(e) => handleFieldChange(index, { name: e.target.value })}
                      placeholder="Название поля"
                      data-testid={`input-field-name-${index}`}
                    />
                  </div>
                  <div className="col-span-3">
                    <Label className="text-xs text-muted-foreground">Тип</Label>
                    <Select
                      value={field.type}
                      onValueChange={(v) => handleFieldChange(index, { type: v as AttributeFieldType })}
                    >
                      <SelectTrigger data-testid={`select-field-type-${index}`}>
                        <SelectValue />
                      </SelectTrigger>
                      <SelectContent>
                        {Object.entries(FIELD_TYPE_LABELS).map(([value, label]) => (
                          <SelectItem key={value} value={value}>{label}</SelectItem>
                        ))}
                      </SelectContent>
                    </Select>
                  </div>
                  <div className="col-span-2 flex items-end gap-2 h-full pb-1">
                    <div className="flex items-center gap-1">
                      <Switch
                        checked={field.required}
                        onCheckedChange={(checked) => handleFieldChange(index, { required: checked })}
                        id={`required-${index}`}
                      />
                      <Label htmlFor={`required-${index}`} className="text-xs">Обяз.</Label>
                    </div>
                  </div>
                  {field.type === "select" && (
                    <div className="col-span-2">
                      <Label className="text-xs text-muted-foreground">Варианты</Label>
                      <Input
                        value={field.options?.join(", ") || ""}
                        onChange={(e) => handleFieldChange(index, { 
                          options: e.target.value.split(",").map(s => s.trim()).filter(Boolean)
                        })}
                        placeholder="a, b, c"
                      />
                    </div>
                  )}
                  <div className="col-span-1 flex items-end h-full pb-1">
                    <Button
                      size="icon"
                      variant="ghost"
                      onClick={() => handleRemoveField(index)}
                      data-testid={`button-remove-field-${index}`}
                    >
                      <Trash2 className="h-4 w-4" />
                    </Button>
                  </div>
                </div>
              ))}

              <Button
                variant="outline"
                className="w-full"
                onClick={handleAddField}
                data-testid="button-add-field"
              >
                <Plus className="h-4 w-4 mr-2" />
                Добавить поле
              </Button>
            </div>
          </ScrollArea>

          <div className="flex justify-end gap-2 px-4 py-3 border-t shrink-0">
            <Button variant="outline" onClick={() => setShowSchemaDialog(false)}>
              Отмена
            </Button>
            <Button onClick={handleSaveSchema} data-testid="button-save-schema">
              Сохранить
            </Button>
          </div>
        </div>
      </DraggableModal>

      <AlertDialog open={showCloseConfirm} onOpenChange={setShowCloseConfirm}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Несохранённые изменения</AlertDialogTitle>
            <AlertDialogDescription>
              У вас есть {pendingEdits.size} несохранённых изменений.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter className="flex-wrap gap-2">
            <AlertDialogCancel onClick={() => setShowCloseConfirm(false)}>
              Отмена
            </AlertDialogCancel>
            <Button variant="destructive" onClick={handleDiscardAndClose}>
              Не сохранять
            </Button>
            <AlertDialogAction onClick={handleSaveAndClose} disabled={isSaving}>
              {isSaving ? "..." : "Сохранить"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}

server/shapefile-parser.ts.content:
import shp from "shpjs";
import simplify from "simplify-js";
import JSZip from "jszip";

interface ParsedFeature {
  geometry: {
    type: string;
    coordinates: any;
  };
  properties: Record<string, any>;
}

interface ParseResult {
  features: ParsedFeature[];
  geometryType: string;
  crs: string;
  fileList: string[];
}

function decodeCP1251(buffer: Buffer): string {
  const cp1251Map: Record<number, string> = {
    0x80: '\u0402', 0x81: '\u0403', 0x82: '\u201A', 0x83: '\u0453', 0x84: '\u201E', 0x85: '\u2026', 0x86: '\u2020', 0x87: '\u2021',
    0x88: '\u20AC', 0x89: '\u2030', 0x8A: '\u0409', 0x8B: '\u2039', 0x8C: '\u040A', 0x8D: '\u040C', 0x8E: '\u040B', 0x8F: '\u040F',
    0x90: '\u0452', 0x91: '\u2018', 0x92: '\u2019', 0x93: '\u201C', 0x94: '\u201D', 0x95: '\u2022', 0x96: '\u2013', 0x97: '\u2014',
    0x99: '\u2122', 0x9A: '\u0459', 0x9B: '\u203A', 0x9C: '\u045A', 0x9D: '\u045C', 0x9E: '\u045B', 0x9F: '\u045F',
    0xA0: '\u00A0', 0xA1: '\u040E', 0xA2: '\u045E', 0xA3: '\u0408', 0xA4: '\u00A4', 0xA5: '\u0490', 0xA6: '\u00A6', 0xA7: '\u00A7',
    0xA8: '\u0401', 0xA9: '\u00A9', 0xAA: '\u0404', 0xAB: '\u00AB', 0xAC: '\u00AC', 0xAD: '\u00AD', 0xAE: '\u00AE', 0xAF: '\u0407',
    0xB0: '\u00B0', 0xB1: '\u00B1', 0xB2: '\u0406', 0xB3: '\u0456', 0xB4: '\u0491', 0xB5: '\u00B5', 0xB6: '\u00B6', 0xB7: '\u00B7',
    0xB8: '\u0451', 0xB9: '\u2116', 0xBA: '\u0454', 0xBB: '\u00BB', 0xBC: '\u0458', 0xBD: '\u0405', 0xBE: '\u0455', 0xBF: '\u0457',
    0xC0: '\u0410', 0xC1: '\u0411', 0xC2: '\u0412', 0xC3: '\u0413', 0xC4: '\u0414', 0xC5: '\u0415', 0xC6: '\u0416', 0xC7: '\u0417',
    0xC8: '\u0418', 0xC9: '\u0419', 0xCA: '\u041A', 0xCB: '\u041B', 0xCC: '\u041C', 0xCD: '\u041D', 0xCE: '\u041E', 0xCF: '\u041F',
    0xD0: '\u0420', 0xD1: '\u0421', 0xD2: '\u0422', 0xD3: '\u0423', 0xD4: '\u0424', 0xD5: '\u0425', 0xD6: '\u0426', 0xD7: '\u0427',
    0xD8: '\u0428', 0xD9: '\u0429', 0xDA: '\u042A', 0xDB: '\u042B', 0xDC: '\u042C', 0xDD: '\u042D', 0xDE: '\u042E', 0xDF: '\u042F',
    0xE0: '\u0430', 0xE1: '\u0431', 0xE2: '\u0432', 0xE3: '\u0433', 0xE4: '\u0434', 0xE5: '\u0435', 0xE6: '\u0436', 0xE7: '\u0437',
    0xE8: '\u0438', 0xE9: '\u0439', 0xEA: '\u043A', 0xEB: '\u043B', 0xEC: '\u043C', 0xED: '\u043D', 0xEE: '\u043E', 0xEF: '\u043F',
    0xF0: '\u0440', 0xF1: '\u0441', 0xF2: '\u0442', 0xF3: '\u0443', 0xF4: '\u0444', 0xF5: '\u0445', 0xF6: '\u0446', 0xF7: '\u0447',
    0xF8: '\u0448', 0xF9: '\u0449', 0xFA: '\u044A', 0xFB: '\u044B', 0xFC: '\u044C', 0xFD: '\u044D', 0xFE: '\u044E', 0xFF: '\u044F',
  };

  let result = '';
  for (let i = 0; i < buffer.length; i++) {
    const byte = buffer[i];
    if (byte < 0x80) {
      result += String.fromCharCode(byte);
    } else {
      result += cp1251Map[byte] || String.fromCharCode(byte);
    }
  }
  return result;
}

function simplifyCoordinates(coordinates: any, tolerance: number, isPolygonRing: boolean = false): any {
  if (!coordinates || !Array.isArray(coordinates) || coordinates.length === 0 || tolerance <= 0) return coordinates;

  // Skip if first element is undefined/null
  if (coordinates[0] === undefined || coordinates[0] === null) {
    return coordinates;
  }

  if (typeof coordinates[0] === 'number') {
    return coordinates;
  }

  // Check if this is a ring of coordinates (array of [x, y] pairs)
  if (Array.isArray(coordinates[0]) && coordinates[0].length >= 2 && typeof coordinates[0][0] === 'number') {
    const points = coordinates.map((c: number[]) => ({ x: c[0], y: c[1] }));
    const simplified = simplify(points, tolerance, true);
    let result = simplified.map((p: { x: number; y: number }) => [p.x, p.y]);

    // Ensure polygon rings remain closed
    if (isPolygonRing && result.length >= 3) {
      const first = result[0];
      const last = result[result.length - 1];
      if (first[0] !== last[0] || first[1] !== last[1]) {
        result.push([...first]);
      }
    }

    return result;
  }

  return coordinates.map((ring: any, index: number) => 
    simplifyCoordinates(ring, tolerance, true)
  );
}

function detectGeometryType(geojson: any): string {
  if (!geojson.features || geojson.features.length === 0) {
    return "Point";
  }

  const firstType = geojson.features[0]?.geometry?.type;
  if (firstType?.includes("Polygon")) return "Polygon";
  if (firstType?.includes("Line")) return "LineString";
  return "Point";
}

function extractCRS(geojson: any): string {
  if (geojson.crs?.properties?.name) {
    const name = geojson.crs.properties.name;
    if (name.includes("4326")) return "EPSG:4326";
    if (name.includes("3857")) return "EPSG:3857";
    const match = name.match(/EPSG::?(\d+)/i);
    if (match) return `EPSG:${match[1]}`;
  }
  return "EPSG:4326";
}

export async function parseShapefileBuffer(
  buffer: Buffer,
  options: { simplifyTolerance?: number } = {}
): Promise<ParseResult> {
  const { simplifyTolerance = 0 } = options;

  const bufferSizeMB = buffer.length / (1024 * 1024);
  console.log(`Parsing shapefile buffer: ${bufferSizeMB.toFixed(2)} MB`);

  if (bufferSizeMB > 50) {
    console.warn(`Large file detected (${bufferSizeMB.toFixed(0)} MB). Processing may take longer and use significant memory.`);
  }

  let geojson: any;
  const fileList: string[] = [];

  try {
    const isZip = buffer[0] === 0x50 && buffer[1] === 0x4B;
    if (!isZip) {
      const cpgBuffer = Buffer.from('CP1251');
      const shapefileObj: any = {
        shp: buffer.buffer.slice(buffer.byteOffset, buffer.byteOffset + buffer.byteLength),
        cpg: cpgBuffer.buffer.slice(cpgBuffer.byteOffset, cpgBuffer.byteOffset + cpgBuffer.byteLength),
      };
      geojson = await shp(shapefileObj);

      const collection = Array.isArray(geojson) ? geojson[0] : geojson;
      if (!collection || !collection.features) {
        throw new Error("Invalid shapefile: no features found");
      }

      const geometryType = detectGeometryType(collection);
      const crs = extractCRS(collection);

      const features: ParsedFeature[] = collection.features.map((feature: any) => {
        let coordinates = feature.geometry?.coordinates;
        if (simplifyTolerance > 0 && geometryType !== "Point") {
          coordinates = simplifyCoordinates(coordinates, simplifyTolerance);
        }
        return {
          geometry: { type: feature.geometry?.type || geometryType, coordinates },
          properties: feature.properties || {},
        };
      });

      return { features, geometryType, crs, fileList: [] };
    }

    const zip = await JSZip.loadAsync(buffer, {
      decodeFileName: (rawBytes: Uint8Array) => {
        const decoder = new TextDecoder('ibm866');
        return decoder.decode(rawBytes);
      }
    } as any);

    const shapefileSets = new Map<string, {
      shp: ArrayBuffer | null;
      shx: ArrayBuffer | null;
      dbf: ArrayBuffer | null;
      prj: string | null;
      cpg: string | null;
      fileNames: string[];
    }>();

    const entries: { path: string; entry: any }[] = [];
    zip.forEach((path: string, entry: any) => {
      entries.push({ path, entry });
    });

    for (const { path, entry } of entries) {
      if (entry.dir) continue;

      const pathLower = path.toLowerCase();
      const ext = pathLower.split('.').pop() || '';

      if (!['shp', 'shx', 'dbf', 'prj', 'cpg'].includes(ext)) continue;

      const pathWithoutExt = path.substring(0, path.lastIndexOf('.'));
      const fileName = path.split('/').pop() || path;

      if (!shapefileSets.has(pathWithoutExt)) {
        shapefileSets.set(pathWithoutExt, {
          shp: null, shx: null, dbf: null, prj: null, cpg: null, fileNames: []
        });
      }

      const set = shapefileSets.get(pathWithoutExt)!;
      set.fileNames.push(fileName);

      if (ext === 'prj' || ext === 'cpg') {
        const content = await entry.async('nodebuffer');
        const text = decodeCP1251(content);
        if (ext === 'prj') set.prj = text;
        if (ext === 'cpg') set.cpg = text;
      } else {
        const content = await entry.async('arraybuffer');
        if (ext === 'shp') set.shp = content;
        if (ext === 'shx') set.shx = content;
        if (ext === 'dbf') set.dbf = content;
      }
    }

    const firstSet = Array.from(shapefileSets.values()).find(s => s.shp !== null);
    if (!firstSet || !firstSet.shp) {
      throw new Error("No .shp file found in archive");
    }

    fileList.push(...firstSet.fileNames);

    const shapefileObj: any = {
      shp: firstSet.shp,
      dbf: firstSet.dbf,
      prj: firstSet.prj,
    };

    const cpgEncoding = firstSet.cpg?.trim() || 'CP1251';
    const cpgBuffer = new TextEncoder().encode(cpgEncoding);
    shapefileObj.cpg = cpgBuffer.buffer;

    console.log(`Parsing shapefile with encoding: ${cpgEncoding}, files: ${firstSet.fileNames.join(', ')}`);

    geojson = await shp(shapefileObj);
  } catch (parseError: any) {
    console.error("shpjs parse error:", parseError);
    if (parseError.message?.includes("memory") || parseError.message?.includes("heap")) {
      throw new Error(`File too large to process. The uncompressed data exceeds memory limits. Try splitting the shapefile into smaller parts.`);
    }
    throw new Error(`Failed to parse shapefile: ${parseError.message || 'Unknown parsing error'}`);
  }

  const collection = Array.isArray(geojson) ? geojson[0] : geojson;

  if (!collection || !collection.features) {
    throw new Error("Invalid shapefile: no features found");
  }

  const geometryType = detectGeometryType(collection);
  const crs = extractCRS(collection);

  const features: ParsedFeature[] = collection.features.map((feature: any) => {
    let coordinates = feature.geometry?.coordinates;

    if (simplifyTolerance > 0 && geometryType !== "Point") {
      coordinates = simplifyCoordinates(coordinates, simplifyTolerance);
    }

    return {
      geometry: {
        type: feature.geometry?.type || geometryType,
        coordinates,
      },
      properties: feature.properties || {},
    };
  });

  return {
    features,
    geometryType,
    crs,
    fileList,
  };
}

export function simplifyFeatureGeometry(
  coordinates: any,
  geometryType: string,
  tolerance: number
): any {
  if (geometryType === "Point" || tolerance <= 0) {
    return coordinates;
  }
  return simplifyCoordinates(coordinates, tolerance);
}

export function getSimplifyTolerance(zoom: number): number {
  if (zoom >= 14) return 0;
  if (zoom >= 12) return 0.000005;
  if (zoom >= 10) return 0.00005;
  if (zoom >= 9) return 0.0003;
  if (zoom >= 8) return 0.001;
  if (zoom >= 7) return 0.003;
  if (zoom >= 6) return 0.006;
  if (zoom >= 5) return 0.015;
  if (zoom >= 4) return 0.03;
  return 0.06;
}

// Point sampling rate based on zoom level (GIS-style approach)
// Returns the sampling divisor: 1 = all points, 5 = every 5th point, etc.
export function getPointSamplingRate(zoom: number): number {
  if (zoom >= 12) return 1;      // All points visible
  if (zoom >= 10) return 5;      // Every 5th point (20%)
  if (zoom >= 8) return 20;      // Every 20th point (5%)
  if (zoom >= 6) return 50;      // Every 50th point (2%)
  return Infinity;               // No points at very low zoom
}

// Deterministic point sampling - ensures same points are shown at same zoom
export function samplePointFeatures<T extends { geometryType: string }>(
  features: T[],
  zoom: number
): { sampled: T[]; totalPoints: number; samplingRate: number } {
  const samplingRate = getPointSamplingRate(zoom);

  // Separate points from other geometry types
  const pointFeatures: T[] = [];
  const otherFeatures: T[] = [];

  for (const feature of features) {
    if (feature.geometryType === "Point" || feature.geometryType === "MultiPoint") {
      pointFeatures.push(feature);
    } else {
      otherFeatures.push(feature);
    }
  }

  // If no sampling needed or no points, return all
  if (samplingRate === 1 || pointFeatures.length === 0) {
    return {
      sampled: features,
      totalPoints: pointFeatures.length,
      samplingRate: 1,
    };
  }

  // If zoom too low, return only non-point features
  if (samplingRate === Infinity) {
    return {
      sampled: otherFeatures,
      totalPoints: pointFeatures.length,
      samplingRate: Infinity,
    };
  }

  // Sample points deterministically by index
  const sampledPoints = pointFeatures.filter((_, index) => index % samplingRate === 0);

  return {
    sampled: [...otherFeatures, ...sampledPoints],
    totalPoints: pointFeatures.length,
    samplingRate,
  };
}

