                  onChange={(e) => setNewUser({ ...newUser, organization: e.target.value })}
                  data-testid="input-new-organization"
                />
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div className="space-y-2">
                <Label htmlFor="new-phone">Номер телефона</Label>
                <Input
