import { useState, useRef, useCallback, useEffect } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { X, GripHorizontal, Minimize2, Maximize2, Minus } from "lucide-react";
import { useIsMobile } from "@/hooks/use-mobile";

interface DraggableModalProps {
  isOpen: boolean;
  onClose: () => void;
  onBeforeClose?: () => boolean | void;
  title: string;
  children: React.ReactNode;
  defaultWidth?: number;
  defaultHeight?: number;
  minWidth?: number;
  minHeight?: number;
}

export function DraggableModal({
  isOpen,
  onClose,
  onBeforeClose,
  title,
  children,
  defaultWidth = 800,
  defaultHeight = 400,
  minWidth = 400,
  minHeight = 200,
}: DraggableModalProps) {
  const isMobile = useIsMobile();
  const [position, setPosition] = useState({ x: 100, y: 100 });
  const [size, setSize] = useState({ width: defaultWidth, height: defaultHeight });
  const [isDragging, setIsDragging] = useState(false);
  const [isResizing, setIsResizing] = useState(false);
  const [resizeDirection, setResizeDirection] = useState<string | null>(null);
  const [isMaximized, setIsMaximized] = useState(false);
  const [isMinimized, setIsMinimized] = useState(false);
  const [preMinimizeSize, setPreMinimizeSize] = useState(size);
  const [preMaximizeState, setPreMaximizeState] = useState({ position, size });

  const modalRef = useRef<HTMLDivElement>(null);
  const dragOffset = useRef({ x: 0, y: 0 });
  const resizeStart = useRef({ x: 0, y: 0, width: 0, height: 0, posX: 0, posY: 0 });

  useEffect(() => {
    if (isOpen && !isMobile) {
      setIsMinimized(false);
      setIsMaximized(false);
      const x = Math.max(50, (window.innerWidth - defaultWidth) / 2);
      const y = Math.max(50, (window.innerHeight - defaultHeight) / 2);
      setPosition({ x, y });
      setSize({ width: defaultWidth, height: defaultHeight });
    }
  }, [isOpen, defaultWidth, defaultHeight, isMobile]);

  const handleMouseDown = useCallback((e: React.MouseEvent) => {
    if (isMaximized || isMobile) return;
    e.preventDefault();
    setIsDragging(true);
    dragOffset.current = {
      x: e.clientX - position.x,
      y: e.clientY - position.y,
    };
  }, [position, isMaximized, isMobile]);

  const handleResizeMouseDown = useCallback((e: React.MouseEvent, direction: string) => {
    if (isMaximized || isMobile) return;
    e.preventDefault();
    e.stopPropagation();
    setIsResizing(true);
    setResizeDirection(direction);
    resizeStart.current = {
      x: e.clientX,
      y: e.clientY,
      width: size.width,
      height: size.height,
      posX: position.x,
      posY: position.y,
    };
  }, [size, position, isMaximized, isMobile]);

  useEffect(() => {
    const handleMouseMove = (e: MouseEvent) => {
      if (isDragging) {
        const newX = Math.max(0, Math.min(window.innerWidth - 100, e.clientX - dragOffset.current.x));
        const newY = Math.max(0, Math.min(window.innerHeight - 50, e.clientY - dragOffset.current.y));
        setPosition({ x: newX, y: newY });
      }

      if (isResizing && resizeDirection) {
        const deltaX = e.clientX - resizeStart.current.x;
        const deltaY = e.clientY - resizeStart.current.y;

        let newWidth = resizeStart.current.width;
        let newHeight = resizeStart.current.height;
        let newX = resizeStart.current.posX;
        let newY = resizeStart.current.posY;

        if (resizeDirection.includes("e")) {
          newWidth = Math.max(minWidth, resizeStart.current.width + deltaX);
        }
        if (resizeDirection.includes("w")) {
          const potentialWidth = resizeStart.current.width - deltaX;
          if (potentialWidth >= minWidth) {
            newWidth = potentialWidth;
            newX = resizeStart.current.posX + deltaX;
          }
        }
        if (resizeDirection.includes("s")) {
          newHeight = Math.max(minHeight, resizeStart.current.height + deltaY);
        }
        if (resizeDirection.includes("n")) {
          const potentialHeight = resizeStart.current.height - deltaY;
          if (potentialHeight >= minHeight) {
            newHeight = potentialHeight;
            newY = resizeStart.current.posY + deltaY;
          }
        }

        setSize({ width: newWidth, height: newHeight });
        setPosition({ x: newX, y: newY });
      }
    };

    const handleMouseUp = () => {
      setIsDragging(false);
      setIsResizing(false);
      setResizeDirection(null);
    };

    if (isDragging || isResizing) {
      document.addEventListener("mousemove", handleMouseMove);
      document.addEventListener("mouseup", handleMouseUp);
      return () => {
        document.removeEventListener("mousemove", handleMouseMove);
        document.removeEventListener("mouseup", handleMouseUp);
      };
    }
  }, [isDragging, isResizing, resizeDirection, minWidth, minHeight]);

  const toggleMinimize = useCallback(() => {
    if (isMobile) return;
    if (isMinimized) {
      setSize(preMinimizeSize);
      setIsMinimized(false);
    } else {
      if (isMaximized) {
        setPosition(preMaximizeState.position);
        setIsMaximized(false);
        setPreMinimizeSize(preMaximizeState.size);
      } else {
        setPreMinimizeSize(size);
      }
      setIsMinimized(true);
    }
  }, [isMinimized, isMaximized, size, preMinimizeSize, preMaximizeState, isMobile]);

  const toggleMaximize = useCallback(() => {
    if (isMobile) return;
    if (isMinimized) {
      setIsMinimized(false);
      setPreMaximizeState({ position, size: preMinimizeSize });
      setPosition({ x: 10, y: 10 });
      setSize({ width: window.innerWidth - 20, height: window.innerHeight - 20 });
      setIsMaximized(true);
      return;
    }
    if (isMaximized) {
      setPosition(preMaximizeState.position);
      setSize(preMaximizeState.size);
      setIsMaximized(false);
    } else {
      setPreMaximizeState({ position, size });
      setPosition({ x: 10, y: 10 });
      setSize({ width: window.innerWidth - 20, height: window.innerHeight - 20 });
      setIsMaximized(true);
    }
  }, [isMaximized, isMinimized, position, size, preMaximizeState, preMinimizeSize, isMobile]);

  const handleClose = useCallback(() => {
    if (onBeforeClose) {
      const shouldPreventClose = onBeforeClose();
      if (shouldPreventClose === true) {
        return;
      }
    }
    onClose();
  }, [onBeforeClose, onClose]);

  if (!isOpen) return null;

  if (isMobile) {
    return (
      <div 
        className="fixed inset-0 z-[60] bg-background flex flex-col"
        data-testid="draggable-modal-mobile"
      >
        <div className="flex items-center justify-between px-4 py-3 border-b bg-muted/50 shrink-0">
          <CardTitle className="text-sm font-medium truncate pr-2">{title}</CardTitle>
          <Button
            size="icon"
            variant="ghost"
            className="h-8 w-8 shrink-0"
            onClick={handleClose}
            data-testid="button-close-modal"
          >
            <X className="h-4 w-4" />
          </Button>
        </div>
        <div className="flex-1 overflow-auto">
          {children}
        </div>
      </div>
    );
  }

  return (
    <div 
      className="fixed inset-0 z-[60] pointer-events-none"
      data-testid="draggable-modal-overlay"
    >
      <Card
        ref={modalRef}
        className="absolute pointer-events-auto bg-background shadow-xl border flex flex-col"
        style={{
          left: position.x,
          top: position.y,
          width: isMinimized ? Math.min(size.width, 320) : size.width,
          height: isMinimized ? 'auto' : size.height,
        }}
        data-testid="draggable-modal"
      >
        <CardHeader 
          className="py-2 px-3 flex flex-row items-center justify-between gap-2 cursor-move border-b shrink-0"
          onMouseDown={handleMouseDown}
        >
          <div className="flex items-center gap-2 min-w-0">
            <GripHorizontal className="h-4 w-4 text-muted-foreground shrink-0" />
            <CardTitle className="text-sm font-medium truncate">{title}</CardTitle>
          </div>
          <div className="flex items-center gap-1 shrink-0">
            <Button
              size="icon"
              variant="ghost"
              className="h-6 w-6"
              onClick={toggleMinimize}
              data-testid="button-toggle-minimize"
              title={isMinimized ? "Развернуть" : "Свернуть"}
            >
              {isMinimized ? <Maximize2 className="h-3 w-3" /> : <Minus className="h-3 w-3" />}
            </Button>
            {!isMinimized && (
              <Button
                size="icon"
                variant="ghost"
                className="h-6 w-6"
                onClick={toggleMaximize}
                data-testid="button-toggle-maximize"
              >
                {isMaximized ? <Minimize2 className="h-3 w-3" /> : <Maximize2 className="h-3 w-3" />}
              </Button>
            )}
            <Button
              size="icon"
              variant="ghost"
              className="h-6 w-6"
              onClick={handleClose}
              data-testid="button-close-modal"
            >
              <X className="h-3 w-3" />
            </Button>
          </div>
        </CardHeader>

        {!isMinimized && (
          <CardContent className="p-0 flex-1 overflow-hidden">
            {children}
          </CardContent>
        )}

        {!isMaximized && !isMinimized && (
          <>
            <div
              className="absolute bottom-0 right-0 w-4 h-4 cursor-se-resize"
              onMouseDown={(e) => handleResizeMouseDown(e, "se")}
            />
            <div
              className="absolute bottom-0 left-0 w-4 h-4 cursor-sw-resize"
              onMouseDown={(e) => handleResizeMouseDown(e, "sw")}
            />
            <div
              className="absolute top-0 right-0 w-4 h-4 cursor-ne-resize"
              onMouseDown={(e) => handleResizeMouseDown(e, "ne")}
            />
            <div
              className="absolute top-0 left-0 w-4 h-4 cursor-nw-resize"
              onMouseDown={(e) => handleResizeMouseDown(e, "nw")}
            />
            <div
              className="absolute top-4 bottom-4 right-0 w-1 cursor-e-resize"
              onMouseDown={(e) => handleResizeMouseDown(e, "e")}
            />
            <div
              className="absolute top-4 bottom-4 left-0 w-1 cursor-w-resize"
              onMouseDown={(e) => handleResizeMouseDown(e, "w")}
            />
            <div
              className="absolute left-4 right-4 bottom-0 h-1 cursor-s-resize"
              onMouseDown={(e) => handleResizeMouseDown(e, "s")}
            />
            <div
              className="absolute left-4 right-4 top-0 h-1 cursor-n-resize"
              onMouseDown={(e) => handleResizeMouseDown(e, "n")}
            />
          </>
        )}
      </Card>
    </div>
  );
}

client/src/hooks/use-drawing.ts.content:
import { useState, useCallback, useRef, useEffect } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { queryClient, apiRequest } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { useScene } from "@/contexts/scene-context";
import type { 
  EditableLayer, 
  InsertEditableLayer, 
  DrawnFeature, 
  InsertDrawnFeature,
  LayerSchemaDefinition,
  AttributeField,
  GeometryType,
} from "@shared/schema";
import type { DrawingMode } from "@/components/drawing-toolbar";

interface UndoAction {
  type: "create" | "update" | "delete";
  featureId: number;
  layerId: number;
  previousData?: DrawnFeature;
  newData?: InsertDrawnFeature;
}

export interface SnapSettings {
  enabled: boolean;
  snapToVertices: boolean;
  snapToEdges: boolean;
  snapRadius: number;
  snapLayerIds: number[]; // empty array = all visible layers
}

interface UseDrawingOptions {
  drawActionsRef?: React.MutableRefObject<{ removeLastPoint: () => boolean; abortDrawing: () => void } | null>;
}

export function useDrawing(options: UseDrawingOptions = {}) {
  const { drawActionsRef } = options;
  const { toast } = useToast();
  const { currentSceneId } = useScene();

  // State
  const [activeLayerId, setActiveLayerId] = useState<number | null>(null);
  const [drawingMode, setDrawingMode] = useState<DrawingMode>("select");
  const [selectedFeatureIds, setSelectedFeatureIds] = useState<number[]>([]);

  // Snap settings
  const [snapSettings, setSnapSettings] = useState<SnapSettings>({
    enabled: false,
    snapToVertices: true,
    snapToEdges: true,
    snapRadius: 15,
    snapLayerIds: [],
  });

  // Undo/redo stacks
  const undoStack = useRef<UndoAction[]>([]);
  const redoStack = useRef<UndoAction[]>([]);
  const [canUndo, setCanUndo] = useState(false);
  const [canRedo, setCanRedo] = useState(false);

  // Queries - load editable layers for current scene
  const { data: editableLayers = [], isLoading: layersLoading } = useQuery<EditableLayer[]>({
    queryKey: ["/api/scenes", currentSceneId, "editable-layers"],
    enabled: !!currentSceneId,
  });

  const activeLayer = editableLayers.find(l => l.id === activeLayerId) || null;

  const { data: features = [], isLoading: featuresLoading } = useQuery<DrawnFeature[]>({
    queryKey: ["/api/editable-layers", activeLayerId, "features"],
    enabled: activeLayerId !== null,
  });

  const { data: layerSchema } = useQuery<LayerSchemaDefinition>({
    queryKey: ["/api/editable-layers", activeLayerId, "schema"],
    enabled: activeLayerId !== null,
  });

  // Mutations
  const createLayerMutation = useMutation({
    mutationFn: async (layer: InsertEditableLayer) => {
      // Attach layer to current scene
      const layerWithScene = { ...layer, sceneId: currentSceneId };
      const res = await apiRequest("POST", "/api/editable-layers", layerWithScene);
      return res.json();
    },
    onSuccess: (newLayer: EditableLayer) => {
      queryClient.invalidateQueries({ queryKey: ["/api/scenes", currentSceneId, "editable-layers"] });
      setActiveLayerId(newLayer.id);
      toast({
        title: "Слой создан",
        description: `Слой "${newLayer.name}" готов к редактированию`,
      });
    },
  });

  // Query key for editable layers
  const editableLayersQueryKey = ["/api/scenes", currentSceneId, "editable-layers"];

  const updateLayerMutation = useMutation({
    mutationFn: async ({ id, ...updates }: { id: number } & Partial<InsertEditableLayer>) => {
      const res = await apiRequest("PATCH", `/api/editable-layers/${id}`, updates);
      return res.json();
    },
    onMutate: async (variables) => {
      // Cancel any outgoing refetches
      await queryClient.cancelQueries({ queryKey: editableLayersQueryKey });
      // Snapshot the previous value
      const previousLayers = queryClient.getQueryData<EditableLayer[]>(editableLayersQueryKey);
      // Optimistically update to the new value
      queryClient.setQueryData<EditableLayer[]>(editableLayersQueryKey, (old) => 
        old?.map(layer => layer.id === variables.id ? { ...layer, ...variables } : layer) ?? []
      );
      return { previousLayers };
    },
    onError: (_err, _variables, context) => {
      // Rollback on error
      if (context?.previousLayers) {
        queryClient.setQueryData(editableLayersQueryKey, context.previousLayers);
      }
    },
    onSettled: () => {
      // Always refetch to ensure data is in sync
      queryClient.invalidateQueries({ queryKey: editableLayersQueryKey });
    },
  });

  const deleteLayerMutation = useMutation({
    mutationFn: async (id: number) => {
      await apiRequest("DELETE", `/api/editable-layers/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/scenes", currentSceneId, "editable-layers"] });
      window.dispatchEvent(new Event("viewport-features-invalidate"));
      if (activeLayerId === activeLayerId) {
        setActiveLayerId(null);
      }
      toast({
        title: "Слой удалён",
      });
    },
  });

  const createFeatureMutation = useMutation({
    mutationFn: async (feature: InsertDrawnFeature) => {
      const res = await apiRequest("POST", `/api/editable-layers/${feature.layerId}/features`, feature);
      return res.json();
    },
    onSuccess: (newFeature: DrawnFeature) => {
      queryClient.invalidateQueries({ queryKey: ["/api/editable-layers", activeLayerId, "features"] });
      queryClient.invalidateQueries({ queryKey: ["/api/scenes", currentSceneId, "editable-layers"] });
      window.dispatchEvent(new Event("viewport-features-invalidate"));

      // Add to undo stack
      undoStack.current.push({
        type: "create",
        featureId: newFeature.id,
        layerId: newFeature.layerId,
        newData: {
          layerId: newFeature.layerId,
          geometryType: newFeature.geometryType as GeometryType,
          coordinates: newFeature.coordinates,
          properties: newFeature.properties,
        },
      });
      redoStack.current = [];
      setCanUndo(true);
      setCanRedo(false);
    },
  });

  const updateFeatureMutation = useMutation({
    mutationFn: async ({ id, ...updates }: { id: number } & Partial<InsertDrawnFeature>) => {
      const res = await apiRequest("PATCH", `/api/features/${id}`, updates);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/editable-layers", activeLayerId, "features"] });
      window.dispatchEvent(new Event("viewport-features-invalidate"));
    },
  });

  const deleteFeatureMutation = useMutation({
    mutationFn: async (id: number) => {
      await apiRequest("DELETE", `/api/features/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/editable-layers", activeLayerId, "features"] });
      queryClient.invalidateQueries({ queryKey: ["/api/scenes", currentSceneId, "editable-layers"] });
      window.dispatchEvent(new Event("viewport-features-invalidate"));
    },
  });

  const batchDeleteMutation = useMutation({
    mutationFn: async (ids: number[]) => {
      const res = await apiRequest("POST", "/api/features/batch-delete", { ids });
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/editable-layers", activeLayerId, "features"] });
      queryClient.invalidateQueries({ queryKey: ["/api/scenes", currentSceneId, "editable-layers"] });
      window.dispatchEvent(new Event("viewport-features-invalidate"));
    },
  });

  const batchUpdateMutation = useMutation({
    mutationFn: async (updates: { id: number; properties: Record<string, unknown> }[]) => {
      const res = await apiRequest("PATCH", "/api/features/batch", { updates });
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/editable-layers", activeLayerId, "features"] });
      window.dispatchEvent(new Event("viewport-features-invalidate"));
    },
  });

  const updateSchemaMutation = useMutation({
    mutationFn: async ({ layerId, fields }: { layerId: number; fields: AttributeField[] }) => {
      const res = await apiRequest("PUT", `/api/editable-layers/${layerId}/schema`, { fields });
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/editable-layers", activeLayerId, "schema"] });
      toast({
        title: "Схема сохранена",
      });
    },
  });

  // Actions
  const selectLayer = useCallback((layer: EditableLayer) => {
    setActiveLayerId(layer.id);
    setSelectedFeatureIds([]);
  }, []);

  const createLayer = useCallback((layer: InsertEditableLayer) => {
    createLayerMutation.mutate(layer);
  }, [createLayerMutation]);

  const createFeature = useCallback((
    geometryType: GeometryType,
    coordinates: unknown,
    properties: Record<string, unknown> = {}
  ) => {
    if (!activeLayerId) return;

    createFeatureMutation.mutate({
      layerId: activeLayerId,
      geometryType,
      coordinates,
      properties,
    });
  }, [activeLayerId, createFeatureMutation]);

  const updateFeature = useCallback((featureId: number, updates: Partial<InsertDrawnFeature>) => {
    const feature = features.find(f => f.id === featureId);
    if (!feature) return;

    // Store for undo
    undoStack.current.push({
      type: "update",
      featureId,
      layerId: feature.layerId,
      previousData: { ...feature },
    });
    redoStack.current = [];
    setCanUndo(true);
    setCanRedo(false);

    updateFeatureMutation.mutate({ id: featureId, ...updates });
  }, [features, updateFeatureMutation]);

  const deleteSelectedFeatures = useCallback(() => {
    if (selectedFeatureIds.length === 0) return;

    // Store for undo
    selectedFeatureIds.forEach(id => {
      const feature = features.find(f => f.id === id);
      if (feature) {
        undoStack.current.push({
          type: "delete",
          featureId: id,
          layerId: feature.layerId,
          previousData: { ...feature },
        });
      }
    });
    redoStack.current = [];
    setCanUndo(true);
    setCanRedo(false);

    // Use batch delete for efficiency
    batchDeleteMutation.mutate(selectedFeatureIds);
    setSelectedFeatureIds([]);
  }, [selectedFeatureIds, features, batchDeleteMutation]);

  const batchDeleteFeatures = useCallback((ids: number[]) => {
    if (ids.length === 0) return;

    // Store for undo
    ids.forEach(id => {
      const feature = features.find(f => f.id === id);
      if (feature) {
        undoStack.current.push({
          type: "delete",
          featureId: id,
          layerId: feature.layerId,
          previousData: { ...feature },
        });
      }
    });
    redoStack.current = [];
    setCanUndo(true);
    setCanRedo(false);

    batchDeleteMutation.mutate(ids);
    setSelectedFeatureIds(prev => prev.filter(id => !ids.includes(id)));
  }, [features, batchDeleteMutation]);

  const batchUpdateFeatures = useCallback((updates: { id: number; properties: Record<string, unknown> }[]) => {
    if (updates.length === 0) return Promise.resolve();

    // Filter out any invalid updates
    const validUpdates = updates.filter(u => typeof u.id === 'number' && !isNaN(u.id) && u.id > 0);

    if (validUpdates.length === 0) {
      console.warn("No valid updates to process");
      return Promise.resolve();
    }

    // Store for undo
    validUpdates.forEach(update => {
      const feature = features.find(f => f.id === update.id);
      if (feature) {
        undoStack.current.push({
          type: "update",
          featureId: update.id,
          layerId: feature.layerId,
          previousData: { ...feature },
        });
      }
    });
    redoStack.current = [];
    setCanUndo(true);
    setCanRedo(false);

    return batchUpdateMutation.mutateAsync(validUpdates);
  }, [features, batchUpdateMutation]);

  const selectFeature = useCallback((featureId: number, multi = false) => {
    if (multi) {
      setSelectedFeatureIds(prev => 
        prev.includes(featureId) 
          ? prev.filter(id => id !== featureId)
          : [...prev, featureId]
      );
    } else {
      setSelectedFeatureIds([featureId]);
    }
  }, []);

  const clearSelection = useCallback(() => {
    setSelectedFeatureIds([]);
  }, []);

  const selectAllFeatures = useCallback((featureIds: number[]) => {
    setSelectedFeatureIds(featureIds);
  }, []);

  const updateSchema = useCallback((fields: AttributeField[]) => {
    if (!activeLayerId) return;
    updateSchemaMutation.mutate({ layerId: activeLayerId, fields });
  }, [activeLayerId, updateSchemaMutation]);

  // Snap functions
  const toggleSnap = useCallback(() => {
    setSnapSettings(prev => ({ ...prev, enabled: !prev.enabled }));
  }, []);

  const updateSnapSettings = useCallback((updates: Partial<SnapSettings>) => {
    setSnapSettings(prev => ({ ...prev, ...updates }));
  }, []);

  const undo = useCallback(() => {
    const action = undoStack.current.pop();
    if (!action) return;

    if (action.type === "create") {
      // Undo creation = delete
      deleteFeatureMutation.mutate(action.featureId);
      redoStack.current.push(action);
    } else if (action.type === "delete" && action.previousData) {
      // Undo deletion = recreate
      createFeatureMutation.mutate({
        layerId: action.previousData.layerId,
        geometryType: action.previousData.geometryType as GeometryType,
        coordinates: action.previousData.coordinates,
        properties: action.previousData.properties,
      });
      redoStack.current.push(action);
    } else if (action.type === "update" && action.previousData) {
      // Undo update = restore previous
      updateFeatureMutation.mutate({
        id: action.featureId,
        coordinates: action.previousData.coordinates,
        properties: action.previousData.properties,
      });
      redoStack.current.push(action);
    }

    setCanUndo(undoStack.current.length > 0);
    setCanRedo(true);
  }, [createFeatureMutation, updateFeatureMutation, deleteFeatureMutation]);

  const redo = useCallback(() => {
    const action = redoStack.current.pop();
    if (!action) return;

    if (action.type === "create" && action.newData) {
      createFeatureMutation.mutate(action.newData);
      undoStack.current.push(action);
    } else if (action.type === "delete") {
      deleteFeatureMutation.mutate(action.featureId);
      undoStack.current.push(action);
    } else if (action.type === "update" && action.previousData) {
      // Already have the new state, just need to swap
      undoStack.current.push(action);
    }

    setCanRedo(redoStack.current.length > 0);
    setCanUndo(true);
  }, [createFeatureMutation, deleteFeatureMutation]);

  const save = useCallback(() => {
    // Data is auto-saved, this is just for UX
    toast({
      title: "Изменения сохранены",
    });
  }, [toast]);

  // Keyboard shortcuts
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Don't trigger if typing in input
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) {
        return;
      }

      if (e.key === "Delete" || e.key === "Backspace") {
        deleteSelectedFeatures();
      } else if (e.key === "Escape") {
        setDrawingMode("select");
        clearSelection();
      } else if (e.key === "v" || e.key === "V") {
        setDrawingMode("select");
      } else if (e.key === "p" || e.key === "P") {
        if (activeLayer) setDrawingMode("point");
      } else if (e.key === "l" || e.key === "L") {
        if (activeLayer) setDrawingMode("line");
      } else if (e.key === "g" || e.key === "G") {
        if (activeLayer) setDrawingMode("polygon");
      } else if (e.key === "m" || e.key === "M") {
        if (activeLayer) setDrawingMode("modify");
      } else if ((e.ctrlKey || e.metaKey) && e.key === "z") {
        e.preventDefault();
        // During line/polygon drawing, try to remove last point first
        if ((drawingMode === "line" || drawingMode === "polygon") && drawActionsRef?.current) {
          const removed = drawActionsRef.current.removeLastPoint();
          if (removed) {
            return; // Successfully removed a point during drawing
          }
        }
        // Fall back to normal undo
        undo();
      } else if ((e.ctrlKey || e.metaKey) && e.key === "y") {
        e.preventDefault();
        redo();
      } else if ((e.ctrlKey || e.metaKey) && e.key === "s") {
        e.preventDefault();
        save();
      } else if (e.key === "s" || e.key === "S") {
        // Toggle snap (only when not Ctrl+S for save)
        if (!e.ctrlKey && !e.metaKey) {
          toggleSnap();
        }
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [activeLayer, deleteSelectedFeatures, clearSelection, undo, redo, save, toggleSnap, drawingMode, drawActionsRef]);

  return {
    // State
    editableLayers,
    activeLayer,
    activeLayerId,
    features,
    layerSchema,
    drawingMode,
    selectedFeatureIds,
    canUndo,
    canRedo,
    snapSettings,

    // Loading states
    isLoading: layersLoading || featuresLoading,
    isSaving: createFeatureMutation.isPending || updateFeatureMutation.isPending || batchUpdateMutation.isPending,
    isDeleting: batchDeleteMutation.isPending,

    // Actions
    setDrawingMode,
    selectLayer,
    createLayer,
    createFeature,
    updateFeature,
    deleteSelectedFeatures,
    batchDeleteFeatures,
    batchUpdateFeatures,
    selectFeature,
    clearSelection,
    selectAllFeatures,
    updateSchema,
    undo,
    redo,
    save,
    deleteLayer: deleteLayerMutation.mutate,
    toggleSnap,
    updateSnapSettings,
  };
}

