import { useState } from "react";
import { ChevronDown, ChevronRight } from "lucide-react";
import type { StyleConfig, CategorizedClass, GraduatedClass, StyleClassItem } from "@shared/schema";
import { isHeatNetworkStyle, getHeatNetworkIconUrl, type HeatNetworkPointStyle } from "@/lib/heat-network-icons";
import { isHeatNetworkLineStyle, getLinePreviewDataUrl, type HeatNetworkLineStyle } from "@/lib/heat-network-lines";

function LegendSymbol({ style }: { style: { color: string; pointStyle?: string; lineStyle?: string } }) {
  const color = style.color || "#888";

  if (style.pointStyle && style.pointStyle !== "circle") {
    if (isHeatNetworkStyle(style.pointStyle)) {
      const iconUrl = getHeatNetworkIconUrl(style.pointStyle as HeatNetworkPointStyle, color);
      return <img src={iconUrl} alt="" className="w-3 h-3 flex-shrink-0" />;
    }
    const shapeMap: Record<string, string> = {
      square: `<rect x="1" y="1" width="10" height="10" fill="${color}" stroke="white" stroke-width="0.5"/>`,
      triangle: `<polygon points="6,1 11,11 1,11" fill="${color}" stroke="white" stroke-width="0.5"/>`,
      diamond: `<polygon points="6,1 11,6 6,11 1,6" fill="${color}" stroke="white" stroke-width="0.5"/>`,
      star: `<polygon points="6,1 7.5,4.5 11,5 8.5,7.5 9,11 6,9 3,11 3.5,7.5 1,5 4.5,4.5" fill="${color}" stroke="white" stroke-width="0.3"/>`,
      cross: `<path d="M5,1 L7,1 L7,5 L11,5 L11,7 L7,7 L7,11 L5,11 L5,7 L1,7 L1,5 L5,5 Z" fill="${color}" stroke="white" stroke-width="0.3"/>`,
      hexagon: `<polygon points="6,1 10.5,3.5 10.5,8.5 6,11 1.5,8.5 1.5,3.5" fill="${color}" stroke="white" stroke-width="0.5"/>`,
      pentagon: `<polygon points="6,1 11,4.5 9,11 3,11 1,4.5" fill="${color}" stroke="white" stroke-width="0.5"/>`,
      cloud: `<polygon points="6,1 8,4 11,5 9,8 10,11 6,10 2,11 3,8 1,5 4,4" fill="${color}" stroke="white" stroke-width="0.3"/>`,
    };
    const svg = shapeMap[style.pointStyle];
    if (svg) {
      const dataUrl = `data:image/svg+xml,${encodeURIComponent(`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 12 12" width="12" height="12">${svg}</svg>`)}`;
      return <img src={dataUrl} alt="" className="w-3 h-3 flex-shrink-0" />;
    }
  }

  if (style.lineStyle && style.lineStyle !== "solid") {
    if (isHeatNetworkLineStyle(style.lineStyle)) {
      return <img src={getLinePreviewDataUrl(style.lineStyle as HeatNetworkLineStyle, color)} alt="" className="w-6 h-3 flex-shrink-0" />;
    }
    let dashArray = "";
    switch (style.lineStyle) {
      case "dashed": dashArray = 'stroke-dasharray="4 2"'; break;
      case "dotted": dashArray = 'stroke-dasharray="1 2"'; break;
      case "dash-dot": dashArray = 'stroke-dasharray="5 2 1 2"'; break;
      case "long-dash": dashArray = 'stroke-dasharray="8 3"'; break;
      case "dash-dot-dot": dashArray = 'stroke-dasharray="5 2 1 2 1 2"'; break;
      case "double": {
        const doubleSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 12" width="24" height="12"><path d="M 1 4 L 23 4" stroke="${color}" stroke-width="1.5"/><path d="M 1 8 L 23 8" stroke="${color}" stroke-width="1.5"/></svg>`;
        return <img src={`data:image/svg+xml,${encodeURIComponent(doubleSvg)}`} alt="" className="w-6 h-3 flex-shrink-0" />;
      }
    }
    const lineSvg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 12" width="24" height="12"><path d="M 1 6 L 23 6" stroke="${color}" stroke-width="2" ${dashArray}/></svg>`;
    return <img src={`data:image/svg+xml,${encodeURIComponent(lineSvg)}`} alt="" className="w-6 h-3 flex-shrink-0" />;
  }

  return (
    <span
      className="w-3 h-3 rounded-sm flex-shrink-0 border border-border/50"
      style={{ backgroundColor: color }}
    />
  );
}

interface LegendLayer {
  id: number;
  name: string;
  color: string;
  visible: boolean;
  styleConfig?: any;
}

interface MapLegendProps {
  layers: LegendLayer[];
}

export function MapLegend({ layers }: MapLegendProps) {
  const [collapsed, setCollapsed] = useState(false);

  const styledLayers = layers.filter(l => {
    if (!l.visible) return false;
    const sc = l.styleConfig as StyleConfig | undefined;
    return sc && sc.renderer !== "single";
  });

  if (styledLayers.length === 0) return null;

  return (
    <div
      className="absolute bottom-4 right-4 bg-background/95 backdrop-blur-sm border rounded-md shadow-sm z-[100] max-w-[240px] text-xs"
      data-testid="map-legend"
    >
      <button
        className="flex items-center gap-1 px-3 py-1.5 w-full text-left font-medium hover-elevate"
        onClick={() => setCollapsed(prev => !prev)}
        data-testid="button-legend-toggle"
      >
        {collapsed ? <ChevronRight className="h-3 w-3" /> : <ChevronDown className="h-3 w-3" />}
        Легенда
      </button>

      {!collapsed && (
        <div className="px-3 pb-2 space-y-2">
          {styledLayers.map(layer => {
            const sc = layer.styleConfig as StyleConfig;
            return (
              <div key={layer.id} data-testid={`legend-layer-${layer.id}`}>
                <p className="font-medium text-muted-foreground mb-1 truncate">{layer.name}</p>
                {sc.renderer === "categorized" && sc.categorizedClasses && (
                  <div className="space-y-0.5">
                    {sc.categorizedClasses.map((cls: CategorizedClass, i: number) => (
                      <div key={i} className="flex items-center gap-1.5">
                        <LegendSymbol style={cls.style} />
                        <span className="truncate">{cls.label || String(cls.value)}</span>
                      </div>
                    ))}
                    {sc.defaultStyle && (
                      <div className="flex items-center gap-1.5">
                        <LegendSymbol style={sc.defaultStyle} />
                        <span className="truncate text-muted-foreground">Прочее</span>
                      </div>
                    )}
                  </div>
                )}
                {sc.renderer === "graduated" && sc.graduatedClasses && (
                  <div className="space-y-0.5">
                    {sc.graduatedClasses.map((cls: GraduatedClass, i: number) => (
                      <div key={i} className="flex items-center gap-1.5">
                        <LegendSymbol style={cls.style} />
                        <span className="truncate">{cls.label}</span>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}

client/src/components/style-config-dialo.content:
import { useState, useEffect, useMemo } from "react";
import { useQuery } from "@tanstack/react-query";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Trash2, Plus, Loader2 } from "lucide-react";
import type { StyleConfig, CategorizedClass, GraduatedClass, StyleClassItem, AttributeField } from "@shared/schema";

const STYLE_COLORS = [
  "#D32F2F", "#F57C00", "#FBC02D", "#388E3C", "#1976D2",
  "#7B1FA2", "#C2185B", "#0097A7", "#512DA8", "#E64A19",
  "#AFB42B", "#00796B", "#303F9F", "#5D4037", "#455A64",
  "#E91E63", "#FF5722", "#8BC34A", "#03A9F4", "#9C27B0",
];

function generateColor(index: number): string {
  return STYLE_COLORS[index % STYLE_COLORS.length];
}

interface StyleConfigDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  layer: {
    id: number;
    name: string;
    geometryType: string;
    color: string;
    styleConfig?: any;
  };
  onSave: (styleConfig: StyleConfig) => void;
}

export function StyleConfigDialog({ open, onOpenChange, layer, onSave }: StyleConfigDialogProps) {
  const existing = layer.styleConfig as StyleConfig | undefined;

  const [renderer, setRenderer] = useState<"single" | "categorized" | "graduated">(
    existing?.renderer || "single"
  );
  const [field, setField] = useState<string>(existing?.field || "");
  const [categorizedClasses, setCategorizedClasses] = useState<CategorizedClass[]>(
    existing?.categorizedClasses || []
  );
  const [graduatedClasses, setGraduatedClasses] = useState<GraduatedClass[]>(
    existing?.graduatedClasses || []
  );
  const [defaultColor, setDefaultColor] = useState<string>(
    existing?.defaultStyle?.color || "#888888"
  );

  useEffect(() => {
    const sc = layer.styleConfig as StyleConfig | undefined;
    setRenderer(sc?.renderer || "single");
    setField(sc?.field || "");
    setCategorizedClasses(sc?.categorizedClasses || []);
    setGraduatedClasses(sc?.graduatedClasses || []);
    setDefaultColor(sc?.defaultStyle?.color || "#888888");
  }, [layer.styleConfig, open]);

  const { data: schemaData } = useQuery<{ layerId: number; fields: AttributeField[] }>({
    queryKey: ["/api/editable-layers", layer.id, "schema"],
    queryFn: async () => {
      const res = await fetch(`/api/editable-layers/${layer.id}/schema`);
      if (!res.ok) return { layerId: layer.id, fields: [] };
      return res.json();
    },
    enabled: open,
  });

  const { data: fallbackAttrs } = useQuery<{ name: string; type: string }[]>({
    queryKey: ["/api/editable-layers", layer.id, "attributes-fallback"],
    queryFn: async () => {
      const res = await fetch(`/api/editable-layers/${layer.id}/attributes`);
      if (!res.ok) return [];
      const data = await res.json();
      const attrs: string[] = Array.isArray(data) ? data : (data.attributes || []);
      return attrs.map((a: any) => ({
        name: typeof a === "string" ? a : (a.name || String(a)),
        type: typeof a === "object" && a.type ? a.type : "text",
      }));
    },
    enabled: open && (!schemaData || schemaData.fields.length === 0),
  });

  const fields = useMemo(() => {
    const schemaFields = schemaData?.fields || [];
    if (schemaFields.length > 0) return schemaFields;
    return (fallbackAttrs || []).map(a => ({
      name: a.name,
      type: a.type as any,
      required: false,
    }));
  }, [schemaData, fallbackAttrs]);

  const numericFields = useMemo(
    () => fields.filter(f => f.type === "number"),
    [fields]
  );

  const { data: uniqueValues, isFetching: isFetchingValues } = useQuery<string[]>({
    queryKey: ["/api/editable-layers", layer.id, "unique-values", field],
    queryFn: async () => {
      const res = await fetch(`/api/editable-layers/${layer.id}/unique-values?field=${encodeURIComponent(field)}`);
      if (!res.ok) return [];
      const data = await res.json();
      return data.values || [];
    },
    enabled: open && renderer === "categorized" && !!field,
  });

  const { data: fieldStats, isFetching: isFetchingStats } = useQuery<{ min: number; max: number; count: number }>({
    queryKey: ["/api/editable-layers", layer.id, "field-stats", field],
    queryFn: async () => {
      const res = await fetch(`/api/editable-layers/${layer.id}/field-stats?field=${encodeURIComponent(field)}`);
      if (!res.ok) return { min: 0, max: 100, count: 0 };
      return res.json();
    },
    enabled: open && renderer === "graduated" && !!field,
  });

  const handleAutoClassify = () => {
    if (!uniqueValues || uniqueValues.length === 0) return;
    const newClasses: CategorizedClass[] = uniqueValues.map((val, i) => ({
      value: val,
      label: String(val),
      style: { color: generateColor(i) },
    }));
    setCategorizedClasses(newClasses);
  };

  const handleAutoGraduate = () => {
    if (!field) return;
    const stats = fieldStats || { min: 0, max: 100, count: 0 };
    const classCount = 5;
    const range = stats.max - stats.min;
    const step = range > 0 ? range / classCount : 20;
    const newClasses: GraduatedClass[] = [];
    for (let i = 0; i < classCount; i++) {
      const min = parseFloat((stats.min + step * i).toFixed(2));
      const max = parseFloat((stats.min + step * (i + 1)).toFixed(2));
      newClasses.push({
        min,
        max,
        label: `${min} - ${max}`,
        style: { color: generateColor(i) },
      });
    }
    setGraduatedClasses(newClasses);
  };

  const handleSave = () => {
    const config: StyleConfig = {
      renderer,
      field: renderer !== "single" ? field : undefined,
      defaultStyle: { color: defaultColor },
    };
    if (renderer === "categorized") {
      config.categorizedClasses = categorizedClasses;
    }
    if (renderer === "graduated") {
      config.graduatedClasses = graduatedClasses;
    }
    onSave(config);
    onOpenChange(false);
  };

  const addCategorizedClass = () => {
    setCategorizedClasses(prev => [
      ...prev,
      {
        value: "",
        label: "",
        style: { color: generateColor(prev.length) },
      },
    ]);
  };

  const updateCategorizedClass = (index: number, updates: Partial<CategorizedClass>) => {
    setCategorizedClasses(prev => prev.map((c, i) => i === index ? { ...c, ...updates } : c));
  };

  const removeCategorizedClass = (index: number) => {
    setCategorizedClasses(prev => prev.filter((_, i) => i !== index));
  };

  const addGraduatedClass = () => {
    const last = graduatedClasses[graduatedClasses.length - 1];
    const newMin = last ? last.max : 0;
    const newMax = newMin + 10;
    setGraduatedClasses(prev => [
      ...prev,
      {
        min: newMin,
        max: newMax,
        label: `${newMin} - ${newMax}`,
        style: { color: generateColor(prev.length) },
      },
    ]);
  };

  const updateGraduatedClass = (index: number, updates: Partial<GraduatedClass>) => {
    setGraduatedClasses(prev => prev.map((c, i) => i === index ? { ...c, ...updates } : c));
  };

  const removeGraduatedClass = (index: number) => {
    setGraduatedClasses(prev => prev.filter((_, i) => i !== index));
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-lg max-h-[85vh] flex flex-col" data-testid="dialog-style-config">
        <DialogHeader>
          <DialogTitle data-testid="text-style-config-title">
            Стилизация: {layer.name}
          </DialogTitle>
        </DialogHeader>

        <div className="space-y-4 flex-1 overflow-hidden flex flex-col">
          <div className="space-y-2">
            <Label>Тип отображения</Label>
            <Select value={renderer} onValueChange={(v) => setRenderer(v as any)}>
              <SelectTrigger data-testid="select-renderer-type">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="single">Единый стиль</SelectItem>
                <SelectItem value="categorized">Категоризированный</SelectItem>
                <SelectItem value="graduated">Градуированный</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {renderer !== "single" && (
            <div className="space-y-2">
              <Label>Поле атрибута</Label>
              <Select value={field} onValueChange={setField}>
                <SelectTrigger data-testid="select-style-field">
                  <SelectValue placeholder="Выберите поле" />
                </SelectTrigger>
                <SelectContent>
                  {(renderer === "graduated" ? numericFields : fields).map(f => (
                    <SelectItem key={f.name} value={f.name}>
                      {f.name} ({f.type})
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
          )}

          <div className="space-y-2">
            <Label>Стиль по умолчанию</Label>
            <div className="flex items-center gap-2">
              <input
                type="color"
                value={defaultColor}
                onChange={(e) => setDefaultColor(e.target.value)}
                className="w-8 h-8 rounded border cursor-pointer"
                data-testid="input-default-color"
              />
              <span className="text-sm text-muted-foreground">
                Для объектов без совпадения
              </span>
            </div>
          </div>

          {renderer === "categorized" && field && (
            <div className="space-y-2 flex-1 overflow-hidden flex flex-col">
              <div className="flex items-center justify-between gap-2 flex-wrap">
                <Label>Классы ({categorizedClasses.length})</Label>
                <div className="flex gap-1">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleAutoClassify}
                    disabled={isFetchingValues}
                    data-testid="button-auto-classify"
                  >
                    {isFetchingValues && <Loader2 className="mr-1 h-3 w-3 animate-spin" />}
                    Автоклассификация
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={addCategorizedClass}
                    data-testid="button-add-class"
                  >
                    <Plus className="h-3 w-3" />
                  </Button>
                </div>
              </div>
              <ScrollArea className="flex-1 min-h-0 max-h-[300px]">
                <div className="space-y-2 pr-3">
                  {categorizedClasses.map((cls, i) => (
                    <div key={i} className="flex items-center gap-2" data-testid={`categorized-class-${i}`}>
                      <input
                        type="color"
                        value={cls.style.color}
                        onChange={(e) => updateCategorizedClass(i, {
                          style: { ...cls.style, color: e.target.value },
                        })}
                        className="w-7 h-7 rounded border cursor-pointer flex-shrink-0"
                        data-testid={`input-class-color-${i}`}
                      />
                      <Input
                        value={String(cls.value)}
                        onChange={(e) => updateCategorizedClass(i, {
                          value: e.target.value,
                          label: e.target.value,
                        })}
                        placeholder="Значение"
                        className="flex-1 h-8 text-sm"
                        data-testid={`input-class-value-${i}`}
                      />
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7 flex-shrink-0"
                        onClick={() => removeCategorizedClass(i)}
                        data-testid={`button-remove-class-${i}`}
                      >
                        <Trash2 className="h-3.5 w-3.5 text-muted-foreground" />
                      </Button>
                    </div>
                  ))}
                  {categorizedClasses.length === 0 && (
                    <p className="text-sm text-muted-foreground py-2">
                      Нажмите "Автоклассификация" для заполнения
                    </p>
                  )}
                </div>
              </ScrollArea>
            </div>
          )}

          {renderer === "graduated" && field && (
            <div className="space-y-2 flex-1 overflow-hidden flex flex-col">
              <div className="flex items-center justify-between gap-2 flex-wrap">
                <Label>Диапазоны ({graduatedClasses.length})</Label>
                <div className="flex gap-1">
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={handleAutoGraduate}
                    disabled={isFetchingStats}
                    data-testid="button-auto-graduate"
                  >
                    {isFetchingStats && <Loader2 className="mr-1 h-3 w-3 animate-spin" />}
                    Авторазбиение
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    onClick={addGraduatedClass}
                    data-testid="button-add-range"
                  >
                    <Plus className="h-3 w-3" />
                  </Button>
                </div>
              </div>
              <ScrollArea className="flex-1 min-h-0 max-h-[300px]">
                <div className="space-y-2 pr-3">
                  {graduatedClasses.map((cls, i) => (
                    <div key={i} className="flex items-center gap-2" data-testid={`graduated-class-${i}`}>
                      <input
                        type="color"
                        value={cls.style.color}
                        onChange={(e) => updateGraduatedClass(i, {
                          style: { ...cls.style, color: e.target.value },
                        })}
                        className="w-7 h-7 rounded border cursor-pointer flex-shrink-0"
                        data-testid={`input-range-color-${i}`}
                      />
                      <Input
                        type="number"
                        value={cls.min}
                        onChange={(e) => {
                          const min = parseFloat(e.target.value) || 0;
                          updateGraduatedClass(i, {
                            min,
                            label: `${min} - ${cls.max}`,
                          });
                        }}
                        placeholder="Мин"
                        className="w-20 h-8 text-sm"
                        data-testid={`input-range-min-${i}`}
                      />
                      <span className="text-muted-foreground text-sm">-</span>
                      <Input
                        type="number"
                        value={cls.max}
                        onChange={(e) => {
                          const max = parseFloat(e.target.value) || 0;
                          updateGraduatedClass(i, {
                            max,
                            label: `${cls.min} - ${max}`,
                          });
                        }}
                        placeholder="Макс"
                        className="w-20 h-8 text-sm"
                        data-testid={`input-range-max-${i}`}
                      />
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-7 w-7 flex-shrink-0"
                        onClick={() => removeGraduatedClass(i)}
                        data-testid={`button-remove-range-${i}`}
                      >
                        <Trash2 className="h-3.5 w-3.5 text-muted-foreground" />
                      </Button>
                    </div>
                  ))}
                  {graduatedClasses.length === 0 && (
                    <p className="text-sm text-muted-foreground py-2">
                      Нажмите "Авторазбиение" для заполнения
                    </p>
                  )}
                </div>
              </ScrollArea>
            </div>
          )}
        </div>

        <DialogFooter className="gap-2">
          <Button variant="outline" onClick={() => onOpenChange(false)} data-testid="button-style-cancel">
            Отмена
          </Button>
          <Button onClick={handleSave} data-testid="button-style-save">
            Сохранить
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

client/src/components/icon-picker.tsx.content:
import { useState, useRef, useCallback } from "react";
import { useQuery, useMutation } from "@tanstack/react-query";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { Upload, Trash2, Loader2, Circle, Square, Triangle, Cloud, Diamond, Star, Plus as CrossIcon, Hexagon, Pentagon } from "lucide-react";
import { queryClient, apiRequest } from "@/lib/queryClient";
import {
  getHeatNetworkPreviewIcon,
  HEAT_NETWORK_LABELS,
  type HeatNetworkPointStyle,
} from "@/lib/heat-network-icons";
import type { CustomIcon, PointStyle } from "@shared/schema";

const BASIC_SHAPES: { value: PointStyle; label: string; icon: typeof Circle }[] = [
  { value: "circle", label: "Круг", icon: Circle },
  { value: "square", label: "Квадрат", icon: Square },
  { value: "triangle", label: "Треугольник", icon: Triangle },
  { value: "cloud", label: "Облако", icon: Cloud },
  { value: "diamond", label: "Ромб", icon: Diamond },
  { value: "star", label: "Звезда", icon: Star },
  { value: "cross", label: "Крест", icon: CrossIcon },
  { value: "hexagon", label: "Шестиугольник", icon: Hexagon },
  { value: "pentagon", label: "Пятиугольник", icon: Pentagon },
];

const HEAT_NETWORK_STYLES: { value: HeatNetworkPointStyle; label: string }[] = Object.entries(
  HEAT_NETWORK_LABELS
).map(([value, label]) => ({ value: value as HeatNetworkPointStyle, label }));

interface IconPickerProps {
  selectedPointStyle?: string;
  selectedCustomIconId?: number;
  color: string;
  onSelect: (selection: { pointStyle?: string; customIconId?: number }) => void;
  disabled?: boolean;
}

function getCustomIconPreview(svgContent: string, color: string): string {
  let svg = svgContent;

  const svgTagMatch = svg.match(/<svg([^>]*)>/i);
  if (svgTagMatch) {
    let attrs = svgTagMatch[1];
    const hasViewBox = /viewBox/i.test(attrs);
    if (!hasViewBox) {
      const wMatch = attrs.match(/\bwidth\s*=\s*["']?(\d+(?:\.\d+)?)/i);
      const hMatch = attrs.match(/\bheight\s*=\s*["']?(\d+(?:\.\d+)?)/i);
      if (wMatch && hMatch) {
        attrs += ` viewBox="0 0 ${wMatch[1]} ${hMatch[1]}"`;
      } else {
        attrs += ` viewBox="0 0 24 24"`;
      }
    }
    attrs = attrs.replace(/\bwidth\s*=\s*["'][^"']*["']/gi, '');
    attrs = attrs.replace(/\bheight\s*=\s*["'][^"']*["']/gi, '');
    attrs += ` width="24" height="24"`;
    svg = svg.replace(/<svg[^>]*>/i, `<svg${attrs}>`);
  }

  svg = svg.replace(/\{color\}/g, color);
  svg = svg.replace(/currentColor/gi, color);
  const encoded = encodeURIComponent(svg);
  return `data:image/svg+xml,${encoded}`;
}

export function IconPicker({
  selectedPointStyle,
  selectedCustomIconId,
  color,
  onSelect,
  disabled,
}: IconPickerProps) {
  const [open, setOpen] = useState(false);

  const { data: customIcons = [] } = useQuery<CustomIcon[]>({
    queryKey: ["/api/custom-icons"],
    enabled: open,
  });

  const uploadMutation = useMutation({
    mutationFn: async (data: { name: string; svgContent: string }) => {
      const res = await apiRequest("POST", "/api/custom-icons", data);
      return res.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/custom-icons"] });
    },
  });

  const deleteMutation = useMutation({
    mutationFn: async (id: number) => {
      await apiRequest("DELETE", `/api/custom-icons/${id}`);
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/custom-icons"] });
    },
  });

  const fileInputRef = useRef<HTMLInputElement>(null);

  const handleFileUpload = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (ev) => {
        const content = ev.target?.result as string;
        if (content && content.includes("<svg")) {
          const name = file.name.replace(/\.svg$/i, "");
          uploadMutation.mutate({ name, svgContent: content });
        }
      };
      reader.readAsText(file);
      if (fileInputRef.current) fileInputRef.current.value = "";
    },
    [uploadMutation]
  );

  const handleSelect = (selection: { pointStyle?: string; customIconId?: number }) => {
    onSelect(selection);
    setOpen(false);
  };

  const isBasicSelected = (v: string) =>
    !selectedCustomIconId && selectedPointStyle === v;
  const isHeatSelected = (v: string) =>
    !selectedCustomIconId && selectedPointStyle === v;
  const isCustomSelected = (id: number) =>
    selectedCustomIconId === id;

  const previewElement = (() => {
    if (selectedCustomIconId) {
      const icon = customIcons.find((i) => i.id === selectedCustomIconId);
      if (icon) {
        return (
          <img
            src={getCustomIconPreview(icon.svgContent, color)}
            alt={icon.name}
            className="h-5 w-5"
          />
        );
      }
    }
    if (selectedPointStyle) {
      const basic = BASIC_SHAPES.find((s) => s.value === selectedPointStyle);
      if (basic) {
        const Icon = basic.icon;
        return <Icon className="h-4 w-4" style={{ color }} />;
      }
      const isHeat = Object.keys(HEAT_NETWORK_LABELS).includes(selectedPointStyle);
      if (isHeat) {
        return (
          <img
            src={getHeatNetworkPreviewIcon(selectedPointStyle as HeatNetworkPointStyle, color)}
            alt=""
            className="h-5 w-5"
          />
        );
      }
    }
    return <Circle className="h-4 w-4" style={{ color }} />;
  })();

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          disabled={disabled}
          className="h-8 w-8 flex items-center justify-center rounded border border-border disabled:opacity-50 hover-elevate"
          data-testid="button-icon-picker"
        >
          {previewElement}
        </button>
      </PopoverTrigger>
      <PopoverContent className="w-72 p-0" align="start" data-testid="popover-icon-picker">
        <Tabs defaultValue="basic" className="w-full">
          <TabsList className="w-full grid grid-cols-3 rounded-none border-b">
            <TabsTrigger value="basic" className="text-xs" data-testid="tab-basic-shapes">
              Базовые
            </TabsTrigger>
            <TabsTrigger value="gost" className="text-xs" data-testid="tab-gost-icons">
              ГОСТ
            </TabsTrigger>
            <TabsTrigger value="custom" className="text-xs" data-testid="tab-custom-icons">
              Свои
            </TabsTrigger>
          </TabsList>

          <TabsContent value="basic" className="p-2 m-0">
            <div className="grid grid-cols-4 gap-1">
              {BASIC_SHAPES.map(({ value, label, icon: Icon }) => (
                <Tooltip key={value}>
                  <TooltipTrigger asChild>
                    <button
                      className={`h-9 w-full flex items-center justify-center rounded border ${
                        isBasicSelected(value)
                          ? "bg-primary/20 border-primary"
                          : "border-border"
                      } hover-elevate`}
                      onClick={() => handleSelect({ pointStyle: value })}
                      data-testid={`icon-basic-${value}`}
                    >
                      <Icon className="h-5 w-5" style={{ color }} />
                    </button>
                  </TooltipTrigger>
                  <TooltipContent side="bottom">
                    <p className="text-xs">{label}</p>
                  </TooltipContent>
                </Tooltip>
              ))}
            </div>
          </TabsContent>

          <TabsContent value="gost" className="p-2 m-0">
            <div className="grid grid-cols-4 gap-1">
              {HEAT_NETWORK_STYLES.map(({ value, label }) => (
                <Tooltip key={value}>
                  <TooltipTrigger asChild>
                    <button
                      className={`h-9 w-full flex items-center justify-center rounded border ${
                        isHeatSelected(value)
                          ? "bg-primary/20 border-primary"
                          : "border-border"
                      } hover-elevate`}
                      onClick={() => handleSelect({ pointStyle: value })}
                      data-testid={`icon-gost-${value}`}
                    >
                      <img
                        src={getHeatNetworkPreviewIcon(value, color)}
                        alt={label}
                        className="h-6 w-6"
                      />
                    </button>
                  </TooltipTrigger>
                  <TooltipContent side="bottom">
                    <p className="text-xs">{label}</p>
                  </TooltipContent>
                </Tooltip>
              ))}
            </div>
          </TabsContent>

          <TabsContent value="custom" className="p-2 m-0">
            <ScrollArea className="max-h-[200px]">
              <div className="grid grid-cols-4 gap-1">
                {customIcons.map((icon) => (
                  <Tooltip key={icon.id}>
                    <TooltipTrigger asChild>
                      <div className="relative group">
                        <button
                          className={`h-9 w-full flex items-center justify-center rounded border ${
                            isCustomSelected(icon.id)
                              ? "bg-primary/20 border-primary"
                              : "border-border"
                          } hover-elevate`}
                          onClick={() =>
                            handleSelect({ customIconId: icon.id, pointStyle: undefined })
                          }
                          data-testid={`icon-custom-${icon.id}`}
                        >
                          <img
                            src={getCustomIconPreview(icon.svgContent, color)}
                            alt={icon.name}
                            className="h-6 w-6"
                          />
                        </button>
                        <button
                          className="absolute -top-1 -right-1 h-4 w-4 rounded-full bg-destructive text-destructive-foreground flex items-center justify-center invisible group-hover:visible"
                          onClick={(e) => {
                            e.stopPropagation();
                            deleteMutation.mutate(icon.id);
                          }}
                          data-testid={`button-delete-icon-${icon.id}`}
                        >
                          <Trash2 className="h-2.5 w-2.5" />
                        </button>
                      </div>
                    </TooltipTrigger>
                    <TooltipContent side="bottom">
                      <p className="text-xs">{icon.name}</p>
                    </TooltipContent>
                  </Tooltip>
                ))}
              </div>
            </ScrollArea>
            <div className="mt-2 pt-2 border-t">
              <input
                ref={fileInputRef}
                type="file"
                accept=".svg"
                className="hidden"
                onChange={handleFileUpload}
                data-testid="input-upload-svg"
              />
              <Button
                variant="outline"
                size="sm"
                className="w-full text-xs"
                onClick={() => fileInputRef.current?.click()}
                disabled={uploadMutation.isPending}
                data-testid="button-upload-svg"
              >
                {uploadMutation.isPending ? (
                  <Loader2 className="h-3 w-3 mr-1 animate-spin" />
                ) : (
                  <Upload className="h-3 w-3 mr-1" />
                )}
                Загрузить SVG
              </Button>
            </div>
          </TabsContent>
        </Tabs>
      </PopoverContent>
    </Popover>
  );
}

export { getCustomIconPreview };

